quests[29177] = { id = 29177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vigilance on Wings", description = "The agents of Twilight continue their assault within this pocket of the Firelands. We must not let our offensive fall! Take wing, and destroy as many of those lancers as you can!\n\nDo not forget to pick up and equip your lance first.", sourceObjective = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Lancers by flying into them. Press the flap button to flap your mount's wings!", progress = "Our vigilance must not fall. Especially not now, in this most trying of times!", completion = "Well done, {class}. I hope you don't forget about us here in the Hatchery.", sourceObjectiveStatus = "unverified-source-field" }
quests[29179] = { id = 29179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Elements", description = "The elementals continue to press on us, and I do not expect them to subside any time soon.\n\nYou'll find them pouring across the Ashen Fields to the north. Thin their ranks.", sourceObjective = "Kill 8 Charred Soldiers or Charred Vanquishers.", progress = "We cannot allow these elementals to take any ground. They're not likely to lapse in their attacks long enough for us to take it back.", completion = "Your continued efforts are appreciated, {class}. We will win this war as long as people like you stand beside us.", sourceObjectiveStatus = "unverified-source-field" }
quests[29180] = { id = 29180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promises, Promises...", description = "My inscrutable theories confirm rumors of vast treasure in Zul'Aman. There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....\n\nOur initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.\n\nForget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman!", sourceObjective = "Retrieve Budd's Map of Zul'Aman from High Priest Nalorakk's terrace in Zul'Aman.", sourceObjectiveStatus = "unverified-source-field" }
quests[29181] = { id = 29181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druids of the Talon", description = "Skylord Omnuron and his Druids of the Talon have been a fearsome force for us back in Hyjal. I know that they prefer the familiar skies of that battlefield, but the time may come when we need them here nonetheless.\n\nIf you get your hands on enough marks, you should appeal to Omnuron that his druids should be on the main front. Omnuron watches out for his own, but he also understands the importance of this effort.", sourceObjective = "Obtain 150 Marks of the World Tree.", progress = "It is good to see you again.", completion = "I see. I can't say I'm eager to bring my flock to the Firelands, but I knew it would become necessary at some point.\n\nWe will be there, {class}. Thank you for carrying the message.", sourceObjectiveStatus = "unverified-source-field" }
quests[29182] = { id = 29182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight of the Storm Crows", description = "Many of the Druids of the Talon have made their way to the Molten Front, at your beckoning. You should go to Skylord Omnuron at Malfurion's Breach and see how their wings are faring in those burning skies.", sourceObjective = "Speak to Skylord Omnuron at Malfurion's Breach.", completion = "These skies are indeed oppressive, but we've been able to navigate them for the most part.\n\nWe may need your help to secure additional landing territory past the Furnace. I will call for you when we are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[29183] = { id = 29183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Tier 2 Heroic (Nth)" }
quests[29185] = { id = 29185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Tier 2 Heroic (1st)" }
quests[29186] = { id = 29186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hex Lord's Fetish", description = "Dis new warlord of da Amani, he be nothin' but an overgrown brute without da protection of a strong witch doctor and he has just dat.\n\nDa new warlord's ally be Hex Lord Malacrass, da most feared witch doctor to walk among da Amani in decades. Without da hex lord's say-so, Daakara won't be submitting his people to da control of da Zandalari.\n\nDefeat Hex Lord Malacrass, bring me his favorite fetish, and I be seein' that ya get a fittin' reward.", sourceObjective = "Obtain the Hex Lord's Fetish from Hex Lord Malacrass in Zul'Aman.", progress = "Have ya eliminated Hex Lord Malacrass?", completion = "So dis is da fetish of da mighty Malacrass? It be a good addition to my collection, {name}. And now, I believe, rewards be in order.", sourceObjectiveStatus = "unverified-source-field" }
quests[29189] = { id = 29189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wicked Webs", description = "Some of our scouts have not reported back for duty. We fear they have succumbed to the deadly spiders in the vicinity.\n\nHope may not be lost, however. The spiders often wrap up their live prey in cocoons for later consumption.\n\nGo search the pillars to the north for cocooned victims. You may yet be able to save some of our brethren.", sourceObjective = "Free 8 victims out of Cinderweb Cocoons.", completion = "Our lost allies have already made it back. They are shaken, but alive. Thank you for rescuing them.", sourceObjectiveStatus = "unverified-source-field" }
quests[29190] = { id = 29190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Go Fly a Kite", description = "The other day, when some of us were out with the matron, I saw a goblin pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time.\n\nI think the goblin's name was Blax Bottlerocket or something. If we can find him, could we get some kites and fly them together? I saw him pushing his cart around the Drag.", sourceObjective = "Purchase a Dragon Kite Two-Pack from Blax Bottlerocket in Orgrimmar's Drag then use it to fly kites with your Orcish Orphan. If your orphan is not present, call for him.", progress = "I thought for sure I was going to have to save all my money for like a million years to get a kite!", completion = "Thanks for the kite, {name}. Every time I fly it, I'll remember the day you gave it to me!", sourceObjectiveStatus = "unverified-source-field" }
quests[29191] = { id = 29191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Scream, I Scream...", description = "There's a brand new ice cream shop in Orgrimmar, and it's not just any old ice cream either. This ice cream is made by a crazy goblin mage! You don't think it's going to disappear if I don't finish it in fifteen minutes, do you?\n\nI bet it tastes really good. Let's go try it!\n\nI heard some of the other kids talking about it, and they were saying the store is called the Cone of Cold and it's in the southern part of the Goblin Slums.", sourceObjective = "Purchase ice cream at Cone of Cold and then share it with your orphan.", progress = "Ice cream is my favorite.", completion = "I think that's the first time I've ever seen a goblin making food that didn't involve a big, noisy machine with a lot of smoke. Maybe more people would like their food if they just made it like normal people... or like mages! That ice cream was so good!", sourceObjectiveStatus = "unverified-source-field" }
quests[29192] = { id = 29192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wardens are Watching", description = "We must tread carefully, {class}. Fandral's Druids of the Flame practice their fiery magic beyond the pillars to the north.\n\nI need you to capture one of those druids alive for questioning. We must seize every opportunity to learn of their plans.\n\nOne of my wardens will accompany you. Follow her instructions if you wish to survive.", sourceObjective = "Attack a Druid of the Flame to weaken it, then lure it into your Shadow Warden's trap.", progress = "The Druids of the Flame have gone beyond redemption. Now they will answer to us for their crimes.", completion = "I am impressed, {class}. Your deeds will be remembered among the Shadow Wardens.", sourceObjectiveStatus = "unverified-source-field" }
quests[29193] = { id = 29193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On a Wing and a Prayer", description = "Time well spent, mortal.\n\nWhile you struggled in the Plane of Fire, my watchers and I were able to determine when and, most importantly, where our vision was obscured.\n\nWe discovered that the shroud was placed over the Nexus, far to the north in the realm of the blue dragonflight.\n\nI have attuned the Timeless Eye to show you the occurrences that remain hidden to us here.\n\nBring it to Coldarra at once and seek out a place suitable for its activation.\n\nGo, child. Time is of the essence...", sourceObjective = "Bring the Timeless Eye to Coldarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[29194] = { id = 29194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through a Glass, Darkly", description = "<Tarecgosa listens as you explain your presence in Coldarra.>\n\nYour tale rings true, {class}. Much has changed since the death of Malygos - little of it for the better.\n\nI know of the device you carry, and I recognize Anachronos' magic in its creation. There is but one place in all of Coldarra that would allow this Timeless Eye to be used discreetly.\n\nYou will require my assistance if you hope to succeed. Speak with me again inside the Nexus and you shall have it.", sourceObjective = "Look into the Eye of Eternity at the Nether Vortex in the Nexus.\n\nMeet Tarecgosa inside the Nexus where she will escort you to the rift.", sourceObjectiveStatus = "unverified-source-field" }
quests[29195] = { id = 29195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ritual of Flame", description = "We appear to have everything under control. Our invasion portal to the Firelands will be opened momentarily, and the elementals have not put up much fight.\n\nAssist our druids by dispatching the last few of these elementals. Then, once the gate has been opened, we can make our move.", sourceObjective = "Fight the waves of Charred Invaders on Nordune Ridge until the portal is opened.", progress = "Continue the fight, {name}. Only a short while longer now.", completion = "Leyara... she lives. I sense Fandral's hand at play here...", sourceObjectiveStatus = "unverified-source-field" }
quests[29196] = { id = 29196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Sanctuary!", description = "We should not worry about this \"Druid of the Flame\" for the time being. We must be concerned with the continuance of our operation.\n\nReturn to Matoclaw at the Sanctuary of Malorne. If Ragnaros was prepared for our arrival, then I anticipate that his forces will launch a counterattack soon.", sourceObjective = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "What happened up there? I saw fire and... never mind, you can tell me later. We have other, more immediate matters to attend to.", sourceObjectiveStatus = "unverified-source-field" }
quests[29197] = { id = 29197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught Unawares", description = "Our invasion plan looks to have backfired. Several of our birds have already reported in, speaking of fires breaking out across the vales of central Hyjal.\n\nNow, many of our druids are stranded out in the field, unprepared for such a large-scale attack. Thisalee was near Ashen Lake, and several others were out in the Regrowth, to the northeast.\n\nGo, {name}! Find them, and make sure that they do not succumb to this backdraft!", sourceObjective = "Help Elderlimb, Thisalee Crow, Tholo Whitehoof and Anren Shadowseeker escape the flames.", progress = "There isn't time! Move!", completion = "{name}! You're back!\n\nThey've pushed us back to the Sanctuary. We are vastly outnumbered. At this rate, the Guardians of Hyjal stand little chance of survival.\n\nI'm glad you're here with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[29198] = { id = 29198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sanctuary Must Not Fall", description = "Malfurion is working on a miracle for us. He believes that, in this time of peril, he can resurrect Malorne to protect the Sanctuary. I have faith in him.\n\nIn the meantime, we need to hold this perimeter. Stand by, and make sure no harm befalls my fellow arch druid.", sourceObjective = "Stand by Malfurion as he resurrects Malorne.", progress = "Please, {name}. Focus on the task at hand.", completion = "Malorne's strength alone may have just saved Kalimdor. To imagine, Malorne has returned today, after so long an absence...\n\n<Malfurion surveys the area.>\n\nWe've taken heavy losses. Though the immediate threat is no longer present, our forces will need time to heal, and to put out any remaining fires here in Hyjal.\n\nOur attack on the Firelands will have to wait.", sourceObjectiveStatus = "unverified-source-field" }
quests[29199] = { id = 29199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling for Reinforcements", description = "We suffered heavy losses during the backdraft after our invasion attempt. Our second attempt cannot fail.\n\nWe need reinforcements before we attempt another invasion. Please, {name}, work with Matoclaw to obtain enough resources to afford reinforcements. Then, we take our second and final stab at the Firelands.", sourceObjective = "Obtain 20 Marks of the World Tree.", progress = "The sooner we can break through our invasion portal, the better.", completion = "Excellent work. I will send for our reinforcements right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[29200] = { id = 29200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyara", description = "Before we depart, {name}, I have another matter to which you should attend.\n\nA Druid of the Flame has been spotted in the ruins to the northwest. I suspect it is the same one that attacked us at the portal several days ago. Now would be an ideal time to see what it is that she truly wants... and if necessary, dispose of her.\n\nSee to this flame druid, then we can continue on our planned course.", sourceObjective = "Find Leyara, the Druid of the Flame.", progress = "Hamuul really shouldn't worry about the affairs of a lone druid. The hour of our attack is at hand!", completion = "<Matoclaw listens intently as you explain what happened.>\n\n<She is visibly distressed.>\n\nYou deviated from our plan, {name}. Our attack was supposed to happen today! All this preparation... how will we succeed without the aid of Hamuul?", sourceObjectiveStatus = "unverified-source-field" }
quests[29201] = { id = 29201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Gates of Hell", description = "There will be time to mourn for Hamuul later. His is the first of many inevitable casualties in this war.... but our attack cannot wait, nor should the momentum we have gained over the last several days be wasted.\n\nThe portal atop Nordune Ridge is now open. Our reinforcements are prepared, and they await only my order to pass through the portal.\n\nWe will meet again on the other side of the portal. Once there, we shall ensure that our foothold is secure.", sourceObjective = "Pass through the portal atop Nordune Ridge and help Malfurion secure a foothold on the Molten Front.", completion = "Very well done, {class}. We've managed to take a foothold in our enemy's realm without their notice. Our armies are moving through to establish a front as we speak.\n\nWe have a long, brutal war ahead of us. It is my hope that you'll be around to help us see it through.", sourceObjectiveStatus = "unverified-source-field" }
quests[29202] = { id = 29202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Runetotem", description = "I apologize for speaking curtly with you earlier. The loss of Hamuul was shocking to me, and difficult to cope with.\n\nThey brought in his body while you were away. He is alive, but - as you might imagine - he is very, very badly burned.\n\nThe scars are deep. He may not live.\n\nI have arranged for some of our finest healers to attend to him. If it is not too much to ask, would you speak with Dorda'en Nightweaver? He and his fellow attendants may need your help.", sourceObjective = "Speak with Dorda'en Nightweaver at the Sanctuary of Malorne in Mount Hyjal.", completion = "Yes, Hamuul lives. You can visit him in the tent behind me, but please, be careful. He is in a fragile condition, and we are doing everything in our power just to keep him alive and comfortable.\n\nWhoever did this to the Arch Druid showed no mercy. I hope that you are someday able to return the favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29203] = { id = 29203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Depths", description = "Leyara has been spotted in the Igneous Depths. A group of Shadow Wardens has cornered her.\n\nGo there immediately. I will join you as soon as I make one necessary preparation.", sourceObjective = "Kill Leyara.", completion = "Leyara's tale is a tragic one. It pains me that it came to this.\n\nStaghelm must be stopped, before he drags anyone else down with him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29204] = { id = 29204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Charge", description = "Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise.\n\nI've assigned her a large number of our men, but her chances of success would be greatly increased if you join her cause. It's your decision, {name}.", sourceObjective = "If you want to help the Wardens attack the Forlorn Spire, seek out Captain Saynna Stormrunner in northeastern Ashen Fields.", sourceObjectiveStatus = "unverified-source-field" }
quests[29205] = { id = 29205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forlorn Spire", description = "Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise.\n\nGo there and escort one of her druids to the tower with any forces that she can spare. You'll have quite a fight ahead of you - make sure the druid lives to see the end of it or they'll not be able to seize the tower.", sourceObjective = "Protect one of the druids attempting to take the Forlorn Spire.", completion = "Well done, {class}. This should prove a good staging ground for pushing further into enemy territory.\n\nI sense Druids of the Flame nearby. Perhaps we shall have some sport of them as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[29206] = { id = 29206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fire", description = "Skylord Omnuron and his druids are seeking to push through the Furnace to our northwest. They've been able to fly over the dangers, but they really need someone on the ground to help them secure the territory past the fire... someone like you.\n\nIf you want to aid the Druids of the Talon, wait for one of Omnuron's Windcallers to start pushing through the fire, stay close to him, and keep him safe from any attackers within the flames.", sourceObjective = "Escort a Windcaller through the Furnace and secure the entrance to the Molten Flow.", completion = "Glad to see the Skylord was finally able to get someone capable through without wings. Our flight has been of little use to us in these confined spaces and amidst the thermals beyond this ridge.\n\nLooks like we'll have to resort to more conventional tactics. You game?", sourceObjectiveStatus = "unverified-source-field" }
quests[29208] = { id = 29208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Friend", sourceObjective = "Among all of the raptors in Mandokir's domain, one familiar face stands out. She's grown a little bigger, and she's earned a few scars, but the lashtail hatchling is still here.\n\nShe recognizes you. Her father has finally come back to save her.", sourceObjectiveStatus = "unverified-source-field" }
quests[29209] = { id = 29209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fiery Depths", description = "One of our druids moved ahead into the Igneous Depths in pursuit of a Druid of the Flame.\n\nGo to her. Help her.", sourceObjective = "Speak to Theresa Barkskin in the Igneous Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[29210] = { id = 29210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enduring the Heat", description = "Shalis has gone with one of our druids to stop a Druid of the Flame that is performing a summoning ritual in the Igneous Depths, below us. They have been tasked with killing the druid, but I need you to stop the ritual.\n\nYou'll find the entrance to the cavern east of the Magma Springs. Once inside, you'll see 8 blue runes spread throughout the cavern. You can use these runes to protect you from the fiery creatures, but you need to stamp all of them out to end the ritual. You will need to be swift.", sourceObjective = "Find your way to the Igneous Depths, then destroy all 8 of the blue runes within.", progress = "You must destroy the runes! Hurry!", completion = "Well done!\n\nThey've been attempting to start rituals of this sort all over the Molten Front, but we've been able to thwart them every time so far. Hopefully you will be present in the future to help us keep up that trend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29211] = { id = 29211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solar Core Destruction", description = "The fight has taken us to Fandral's doorstep. His druids are channeling energies of the Firelands into a vessel called the Solar Core.\n\nShould this vessel detonate on Azeroth, none of us will have a home to return to.\n\nWe need to strike at the Solar Core now, while it is still vulnerable. You can find the infernal device to the northeast.", sourceObjective = "Detonate the Solar Core.", completion = "It is destroyed? Good. I doubt this will deter Fandral for long, but we must gain every advantage we can muster.", sourceObjectiveStatus = "unverified-source-field" }
quests[29213] = { id = 29213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How's the Hunter Holding Up?", description = "Tings ain't looking good.  Dat panther was under some powerful magic.  We better check on dat hunter an' see how he be doin'.", sourceObjective = "Check on Grent Direhammer.", completion = "Oh... Me spine...  Brother, is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[29214] = { id = 29214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Wardens", description = "The Shadow Wardens are back in the Regrowth. I know that they take the loss of Fandral from their custody very seriously, so it wouldn't take much prodding to bring them to the Firelands to hunt the Druids of the Flame, and perhaps aid us otherwise in the process.\n\nShould you come upon enough marks, you should seek out Captain Saynna Stormrunner at the Sanctuary of Malorne and secure her aid.", sourceObjective = "Obtain 150 Marks of the World Tree.", progress = "Yes, {class}?", completion = "I see. It is time for us to join the hunt in the Firelands then. My sisters will be with you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29215] = { id = 29215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt Begins", description = "The Shadow Wardens have joined the fight at the Molten Front, on your request. You should find Captain Saynna Stormrunner and see to it that they've found a way to best apply their skills.", sourceObjective = "Speak to Captain Saynna Stormrunner at Malfurion's Breach.", completion = "Hello, {name}. It's good to see you again.\n\nYou needn't worry. We've settled in quite well. I've dispatched several of my wardens to assist in hunting down the Druids of the Flame, and I've drawn assault plans for the Forlorn Spire. When the time is right, perhaps you will join us there.", sourceObjectiveStatus = "unverified-source-field" }
quests[29216] = { id = 29216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion's Breach", sourceObjective = "Secure a foothold in the Firelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[29217] = { id = 29217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Scouts", description = "After we arrived, I dispatched my scouts to learn more about da Zandalari presence here in Zul'Aman. Many returned with useful information, but four still be missin'. If we do not act quickly, da new warlord's lieutenants will offer dem as sacrifices in honor of da Zandalari emissaries.\n\nFind my scouts, {name}, and free dem before da priests offer dem as sacrifices!", sourceObjective = "Free the captive scouts: Hazlek, Bakkalzu, Norkani, and Kasha. They are being held captive by the Amani high priests.", progress = "Did ya find my scouts?", completion = "I hadn't expected to see dem again, {name}. The information dey gathered will be da key to destroying Zandalari influence in Zul'Aman. Ya have my thanks and da thanks of my scouts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29218] = { id = 29218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marks of the World Tree" }
quests[29219] = { id = 29219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bwemba's Spirit", description = "Dese be troublin' times for us Darkspear.  Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost.\n\nWe tryin' to warn all dat we can.  But it might be too late.\n\nAnother Darkspear gone down to Stranglethorn to warn da people.  But it ain't safe to travel alone in Stranglethorn.\n\nHelp me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes.\n\nI gonna bind my spirit wit' ya.  When ya get to Stranglethorn, I be able to aid ya.", sourceObjective = "Warn the people of Stranglethorn and find the other Darkspear emissary.", progress = "Dis won't be no easy task, {name}.", completion = "Dere ya have it, {name}.  It look like we gonna lead an assault on da Gurubashi in Zul'Gurub.\n\nDese be dire times for us Darkspear.  But dey be even more dire for da Zandalar.  Dey goin' too far.\n\nYa been good to Bwemba, hopefully ya gonna continue to help out all of Stranglethorn.\n\nSpirits be wit' ya, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29220] = { id = 29220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bambala", description = "Da first place we check gonna be da place most likely to be attacked first, Bambala.\n\nBambala be dangerously close to da troll city Zul'Gurub... It make for an easy target.\n\nMaybe we find da emissary dere.  Hopefully it ain't too late.", sourceObjective = "Head to Bambala in Northern Stranglethorn Vale to find the Darkspear emissary.", completion = "It seems da spirits be wit' you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29221] = { id = 29221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serpents and Poison", description = "Da warning helped, {name}.\n\nWe gathered more Headhunters to help defend.  But Headhunters... Dey not used to hunting heads on serpents.  So we soon be overwhelmed.  Dese serpents, dey seem to come from everywhere.  An' it probably only gonna get worse.\n\nHelp us and kill da serpents and have Bwemba use her mojo to cure da ones dat are sick from poison.", sourceObjective = "Kill Jungle Serpents and inspect the poisoned Headhunters to allow Bwemba to heal them.", progress = "It don't look like dere be an end to dese serpents.", completion = "Thanks for da help, {name}.  Dese serpents, dere don't seem to be an end to dem.", sourceObjectiveStatus = "unverified-source-field" }
quests[29222] = { id = 29222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits Are With Us", description = "Dere was something about da way da serpents attacked, {name}.  Something unnatural...  Even da poison had a hint of some bad mojo.\n\nDere be a shrine near here wit' a bonfire.  We can use dat to perform a ritual.\n\nWhatever be makin' dese serpents attack, dey probably still watchin' over dem.\n\nDa only problem, {name}, is dat I only be here in spirit form.  I need you to be my hands.  I need you to go to da fire an' prepare it for me.  Den I'll handle da rest.", sourceObjective = "Prepare the bonfire in front of the serpent shrine near Bambala for Bwemba's ritual.", progress = "Stranglethorn be in some bad shape, {name}.", completion = "Venoxis... Dis can't be good, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29223] = { id = 29223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwary Will Know", description = "So da Gurubashi be on da rampage an' dey usin' serpents to lead da charge.\n\nYou know who be good at keepin' da animal population in check?  Da hunters at Nesingwary's Expedition.\n\nHead over dere and see how dey doin'.  See if dey know a good way to get rid of da serpents.\n\nIf dey don't know, den you gotta at least warn dem dat dese serpents, it ain't all natural.", sourceObjective = "Warn the hunters at Nesingwary's Expedition in Northern Stranglethorn Vale.", completion = "We know all about the serpents, {name}.  But there is something else out there lurking...  The jungle has come to life, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29225] = { id = 29225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Actionable Intelligence", description = "<Tarecgosa listens intently as you describe your vision.>\n\nImpossible!\n\nNot even Arygos would dare to go to such lengths.\n\nI do not question your integrity, {class}, but you must understand - your mortal mind can easily be deceived.\n\nRegardless, Kalecgos must be informed of these events. You must travel to Nordrassil at once to seek him out.\n\nI shall remain here to conceal the evidence of our activities. Speak of this to no one else!", sourceObjective = "Speak to Kalecgos at Nordrassil in Mount Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29226] = { id = 29226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Track the Tracker", description = "We've been fending off serpents for days now, {name}.  But the serpents are nothing compared to what else is out in that jungle.\n\nWe hunters are being hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer headed off to the east, perhaps you can find them there.", sourceObjective = "Find Grent Direhammer in Northern Stranglethorn Vale.", completion = "Shhh....", sourceObjectiveStatus = "unverified-source-field" }
quests[29227] = { id = 29227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Revenge", description = "The beast that's been hunting us... I've been hunting it.\n\nWe call him Mauti.  He's a clever one.  But he made a grave mistake when he killed my brother.  Now that mistake is going to cost him.  Ol' Direhammer has got his scent.\n\nI've noticed him roaming just above Kurzen's Compound.  If we act fast, we can take him down.\n\nAre you ready, {name}?", sourceObjective = "Give Grent Direhammer the closure he needs by killing Mauti.", sourceObjectiveStatus = "unverified-source-field" }
quests[29228] = { id = 29228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", sourceObjective = "Find where Mauti has taken Grent Direhammer.", progress = "Don't be underestimating Mauti, she be a smart panther, {name}.", completion = "We be here... Da hunter, he be in da cave.  Da beast... Sometin' ain't right about her...", sourceObjectiveStatus = "unverified-source-field" }
quests[29229] = { id = 29229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", sourceObjective = "Find where Mauti has taken Grent Direhammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[29230] = { id = 29230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mauti", description = "I got da feeling dat somethin' ain't right wit' dat panther, {name}.  It ain't natural.  I gonna need to perform some rituals over da body.  Put Mauti down, an' den let's see what we can find out, {name}.", sourceObjective = "Bring Bwemba to the remains of Mauti.", progress = "Mauti, she got some powerful mojo, {name}.", completion = "High Priestess Kilnara be behind dis abomination.  Dis ain't looking good.  We should see to da dwarf and then make our way to see what other trouble be going on.", sourceObjectiveStatus = "unverified-source-field" }
quests[29231] = { id = 29231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How's the Hunter Holding Up?", description = "Tings ain't looking good.  Dat panther was under some powerful magic.  We better check on dat hunter an' see how he be doin'.", sourceObjective = "Check on Grent Direhammer.", completion = "Oh... Me spine...  Brother, is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[29232] = { id = 29232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bury Me With Me Boots...", description = "Ah... It's you, {name}.  Mauti... He's dead?  Then my brother has been avenged.  I've only one request from ya... This scamp here, he's been pawing at me bare feet.  No dwarf should go to the earth with bare feet.\n\nPlease, bury me with me boots.", sourceObjective = "Collect Grent Direhammer's boots.", progress = "Do ya have me boots?  Grant a dwarf his last request will ya?", completion = "Th-thank ye, lad.\n\nPappy...?\n\n\nIs that...\n\n\n\nyou...\n\n\n\n\n...", sourceObjectiveStatus = "unverified-source-field" }
quests[29233] = { id = 29233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Grom'gol", description = "Dis death ain't be in vain, {name}.  We figure out dat Kilnara be on da prowl.  Tings don't look good.\n\nWe better check out Grom'gol Base Camp to da west.  Maybe we find my contact dere.", sourceObjective = "Make your way to Grom'gol Base Camp.", completion = "First we had snakes, then we had panthers, now we have blood-thirsty trolls.\n\nIt's good that you're here, {class}, there are plenty of trolls to kill.", sourceObjectiveStatus = "unverified-source-field" }
quests[29234] = { id = 29234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegation", description = "I am duty-bound to look into your claims immediately, {race}, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the World Tree's branch.", sourceObjective = "Recover the Branch of Nordrassil from the Firelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[29235] = { id = 29235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend Grom'gol", description = "I hope you like to fight, {name}.  Your troll friend has been through here and warned us that the Gurubashi were on the rampage.  I never thought the battle would be this glorious though.\n\nCome, join in our fight and let's show these Gurubashi trolls the might of the Horde!", sourceObjective = "Help defend Grom'gol Base Camp for three minutes.", progress = "There is no end to these trolls, {name}.  I like it that way!", completion = "These trolls just keep coming, {name}.  I love it!\n\nLike I said before, the Darkspear emissary was here for a small amount of time.  He warned us and then left.\n\nThysta, our Wind Rider Master, helped get him to his next destination, maybe she can help you out.\n\nHappy hunting, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29236] = { id = 29236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Hardwrench Hideaway", description = "Bwemba...  Is that you?\n\nYour contact was here.  He was eager to get to the next location and warn them.  And really, who could blame him?  I gave him use of a wyvern to reach the goblins of Hardwrench Hideaway, in the Cape of Stranglethorn.\n\nI will give you use of one of my wyverns to reach Hardwrench.\n\nTalk to me when you are ready to go, {name}.", sourceObjective = "Head to Hardwrench Hideaway in The Cape of Stranglethorn.", progress = "We better hury, {name}.", completion = "Dis don't look very good, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29237] = { id = 29237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoo Zombies", description = "Da people... Dey all zombies, voodoo zombies!  Dis ain't gonna be pretty, {name}.\n\nYou gotta kill dem.\n\nBut once dey killed, dere is a moment where I can save dem.  Change dem back into da person dey were before.\n\nWe gotta act fast.  Da zombies don' rest.", sourceObjective = "Rescue 10 Hideaway Survivors.", progress = "Dis be a rush job wit da voodoo.  But it still be dangerous.", completion = "We done enough, {name}.  We can't keep fighting dese zombies.  We need to figure out da source of dis voodoo.  An' I tink I know where to start...", sourceObjectiveStatus = "unverified-source-field" }
quests[29238] = { id = 29238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Supplies", description = "Some of da survivors mentioned food, {name}.  We better check da food supplies.  I gotta a bad feelin' about dis.", sourceObjective = "Check out the food preparation area in Hardwrench Hideaway.", completion = "Zanzil... Dis is all startin' to come together now.  If I can find my contact den we can formulate a plan of attack.  A way to end dis madness.", sourceObjectiveStatus = "unverified-source-field" }
quests[29239] = { id = 29239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordrassil's Bough", description = "Much has transpired since last we spoke.\n\nI have taken it upon myself to visit the Nexus and recover Anachronos's artifact, but not before using it for myself. Now I too have witnessed that which you have seen.\n\nBefore discussing the matter further, allow me to express my gratitude to you for your assistance, both here and in the Plane of Fire.", sourceObjective = "Collect the Branch of Nordrassil at Amber Ledge in Borean Tundra.", sourceObjectiveStatus = "unverified-source-field" }
quests[29240] = { id = 29240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Extraction", description = "Now, back to the matter at hand...\n\nI am convinced that the vision in the Nexus is one of Deathwing's illusions designed to bring conflict into our flight at a very fragile time.\n\nThe Worldbreaker would only be strengthened were we to fall to infighting.\n\nStill, a gnawing sense of unease tempts me to take a path of caution.\n\nIt would be wise for me to take Tarecgosa and withdraw until the time of choosing.", sourceObjective = "Accompany Kalecgos to Coldarra.\n\nSpeak to him when you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[29241] = { id = 29241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Godbreaker", description = "<Bloodslayer Zala points at the temple in the distance.>\n\nWhen Jin'do was last ripped from dis world, he survived as a shade, weak and broken, in da spirit world.\n\nBut Jin'do always had power over da spirits.  One by one, he broke dem to his will, and wit' each soul devoured, Jin'do got closer ta' rippin' a hole through to dis world.\n\nTa be here now...\n\nDa spirits be wit' us, we must end Jin'do.", sourceObjective = "Kill Jin'do the Godbreaker inside of Zul'Gurub on Heroic difficulty.", progress = "One way or another, we must end Jin'do.", completion = "<Bloodslayer Zala clutches her hand to her chest.>\n\nIt be done, then.  Spilling da blood of our brothers be a grim task.  Da city of da Gurubashi has seen only death an' hatred for years.\n\nMaybe it be time for da jungle ta retake Zul'Gurub, an' wash da scent of death from dis place.\n\nBlood and honor, champion, to da Siame-Quashi you will always be known as \"Bloodslayer\".", sourceObjectiveStatus = "unverified-source-field" }
quests[29242] = { id = 29242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting a Price on Priceless", description = "Listen, friend.  I don't know you, and you don't know me.  But as long as we're both here, there's something Revilgaz wanted me to mention.\n\nMaybe you're taking a stroll through this troll-infested jungle-ocalypse.  Maybe you happen to find a priceless troll artifact or two.  Maybe you bring it back to me and I accidentally leave behind a little present for ya'.\n\nIf you must know, it's for a project.  And no, you can't ask what the project is.", sourceObjective = "Investigate the Cache of Madness and find the Mysterious Gurubashi Bijou.", progress = "So, did you find a thing?  Because my pants are getting pretty heavy from all of this treasure of yours I'm holding onto.", completion = "What have you got there?\n\nA crazy-looking snake idol?  What am I supposed to do with this?  Hit someone over the head with it and steal something that's actually valuable?\n\nThis thing is worthless!\n\n<Briney tosses the Bijou into the water.>\n\nThanks for the \"help,\" I guess.  Here's your \"reward.\"\n\nIdiot.", sourceObjectiveStatus = "unverified-source-field" }
quests[29243] = { id = 29243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike at the Heart", description = "One of Ragnaros' Lieutenants has shown itself at Ragnaros' Reach.  It is time to strike. Captain Saynna has requested that you be there to help see the fight through.\n\nWitherbranch and some others will have joined the battle by the time you arrive.  You should make haste to the northwest and find them.", sourceObjective = "Kill the Lieutenant of Flame.", completion = "Very well done, {name}! This should delay them significantly.\n\nIf we keep this up, we can easily push the fight back to Ragnaros himself.", sourceObjectiveStatus = "unverified-source-field" }
quests[29244] = { id = 29244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lieutenant of Flame", description = "Captain Saynna has requested your presence at Ragnaros' Reach. A Lieutenant of Flame has shown himself and she thinks you are our greatest chance at striking against him.\n\nMake your way there as soon as you're able.", sourceObjective = "Report to Captain Saynna Stormrunner at Ragnaros' Reach.", sourceObjectiveStatus = "unverified-source-field" }
quests[29245] = { id = 29245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysterious Seed", description = "A small, dried acorn has fallen out of the Flame Druid's robe.\n\nWhy would a Druid of the Flame be carrying it around?\n\nPerhaps someone at Malfurion's Breach would like to see it.", sourceObjective = "Take the Acorn to Avrilla at Malfurion's Breach in the Firelands.\n\nProvided item:", completion = "Fascinating! It appears to be an acorn!", sourceObjectiveStatus = "unverified-source-field" }
quests[29246] = { id = 29246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relieving the Pain", description = "The Arch Druid has an immense tolerance for pain. I've treated burn victims that spend twenty-two hours a day screaming in pain, and their burns weren't even half as bad as what Hamuul has suffered.\n\nNevertheless, I can sense that he is in greater discomfort than normal today. Bring me the hearts of the large fire elementals to the southeast. I can use them to prepare a soothing salve for our patient.", sourceObjective = "Obtain 4 Flame-Wreathed Hearts from Seething Firelords.", progress = "These hearts will give us exactly what Hamuul needs to rest.", completion = "I must get to work preparing the salve immediately. These reagents lose their efficacy by the minute.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29247] = { id = 29247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treating the Wounds", description = "We have an ample supply of medical supplies here at the Sanctuary, but we mustn't lose sight of the fact that we are at war. Hamuul isn't the only person who has need of bandages.\n\nThe fiery behemoths that roam Sethria's Roost wear flame-resistant wrappings that will serve Hamuul as ably as any bandage. Bring me those wrappings, and I will prepare them for use on the Arch Druid.", sourceObjective = "Obtain 4 Sulfur-Laced Wrappings from Fiery Behemoths in Sethria's Roost.", progress = "There are some who say that the sulfur in those wrappings has curative properties. Personally, I am unconvinced, but I am willing to endure the smell on the off-chance that it does.", completion = "Many thanks, {class}.\n\nYou do the war effort a favor. Burn victims have a notorious appetite for bandages, and Hamuul is no exception.", sourceObjectiveStatus = "unverified-source-field" }
quests[29248] = { id = 29248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Releasing the Pressure", description = "Having been burned so badly, Arch Druid Hamuul is suffering from edema - swelling of the body's tissues. It takes a great deal of his attendants' effort to keep his swelling down enough for him to breathe.\n\nNormally, to reduce this swelling, we make cuts in his flesh, but he is weak, {name}. I cannot cut him today. I need your help.\n\nFlamewaker scales will aid with the swelling, but you need a lot of them.", sourceObjective = "Obtain 100 Flamewaker Scales.", progress = "Do you have the scales? I hesitate to cut the Arch Druid again, but we must relieve the swelling somehow.", completion = "You are a compassionate {race}. With this many scales, we won't have to cut him again for another day, at least. Perhaps two.", sourceObjectiveStatus = "unverified-source-field" }
quests[29249] = { id = 29249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planting Season", description = "The acorn seems to be unharmed.\n\n<Avrilla shrugs.>\n\nNo point in beating around the bush. Let's plant it and see what comes out.\n\nLuckily for you, we brought some leftover soil with us to help establish our base.\n\nYou'll find the soil at the graveyard directly east.", sourceObjective = "Plant the Acorn in the Un'Goro Soil at Malfurion's Breach.", completion = "A red flower pops its head out of the soil.", sourceObjectiveStatus = "unverified-source-field" }
quests[29250] = { id = 29250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Contact", description = "You aren't one of the zombies...\n\nA troll?  I did see one, just before the outbreak...  He warned us, told us to be on our guard... But it was too late.\n\nYour troll friend headed to Booty Bay to warn them...", sourceObjective = "Head to Booty Bay and find Bwemba's contact.", completion = "I be tellin' Baron Revilgaz about da Zandalar threat now...", sourceObjectiveStatus = "unverified-source-field" }
quests[29251] = { id = 29251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Bay's Interests", description = "Look, {name}.  You've helped out plenty so far, but that's not going to be enough.  I need these crazy trolls stopped, or at least stopped from getting into Booty Bay.\n\nI'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen.\n\nAt the very least, I want you to find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll treat you right.", sourceObjective = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, {name}?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29252] = { id = 29252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Bay's Interests", description = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted.  Or that it is at least halted at the gates of Booty Bay.\n\nI want action and I want results.\n\nI want you to get in there and kill.\n\nI want you to get in there and find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll make sure you get paid.", sourceObjective = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, {name}?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29253] = { id = 29253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shiny Reward", description = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale.\n\nHead to the statue and claim your prize, {class}.", sourceObjective = "Get your reward from a chest in the statue at Janeiro's Point.", completion = "Loot at last!", sourceObjectiveStatus = "unverified-source-field" }
quests[29254] = { id = 29254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Lasher", description = "The little red flower wiggles its tendrils happily. It seems to like you!\n\nPerhaps Avrilla would like to see what grew out of the acorn.", sourceObjective = "Bring the Crimson Lasher to Avrilla.", completion = "Oh my! Who's your little friend? It followed you, you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[29255] = { id = 29255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embergris", description = "The Crimson Lasher has developed some cracking blisters on its vines. Without treatment, this condition could be life threatening.\n\nLuckily, the Charred Soldiers and Charred Vanquishers in the area produce a waxy substance known as Embergris, which should soothe the Lasher's pain.\n\nBring me some of this substance, and kill those nasty fire elementals while you're at it.", sourceObjective = "Retrieve 5 Embergris from Charred Soldiers and Charred Vanquishers.", progress = "The Lasher is growing quite quickly.", completion = "It isn't very pleasant-smelling, but this should fix the Lasher right up.", sourceObjectiveStatus = "unverified-source-field" }
quests[29257] = { id = 29257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steal Magmolias", description = "We've discovered a new species of flower growing in the Magma Springs to the north. Amazingly, they sustain themselves in pure molten lava!\n\nPlease go and retrieve some specimens for me. I'm sure that further study of these plants will shed some light on your little friend here.\n\nSpeaking of which, he seems quite eager to go with you. Let's hope he behaves himself.", sourceObjective = "Collect 8 Magmolias from the Magma Springs to the north.", progress = "Fascinating! The more time I spend in the Firelands, the more I see there is an ecosystem at work here.", completion = "Thank you, {name}. I will start analyzing these samples at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[29258] = { id = 29258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meteorite Hunt" }
quests[29261] = { id = 29261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Aman Voodoo", progress = "The maker of this voodoo pile perished in the process.  Perhaps if you could finish it, the spirits would protect you instead....", completion = "The tablet provides the final incantation to bind the voodoo pile's magic to you and your party!" }
quests[29262] = { id = 29262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Gurub Voodoo", progress = "This potent pile of voodoo witchery emanates strong mojo...", completion = "As you slip the tablet into the voodoo pile, a primal screech shatters the silence." }
quests[29263] = { id = 29263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bitter Pill", description = "As far as I'm concerned, there's no problem that can't be solved with bombs. And if a bomb doesn't solve your problem on the first try... use a bigger bomb.\n\nSo there's this big worm that's been eating people near the lava pools up north. Search for breath bubbles to find it. Attack it until it prepares to bite, then place this bomb down in front of it. Then sit back and watch the fireworks.\n\nHmm... there was one other thing I wanted to say... oh yeah! Don't get eaten.", sourceObjective = "Find the Subterranean Magma Worm's breath bubbles, then defeat it by making it swallow the Bitter Pill.", completion = "Ah knew Ricket's bombs'd come in handy. Twas just a matter ah findin' somethin' big enough to explode.", sourceObjectiveStatus = "unverified-source-field" }
quests[29264] = { id = 29264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flamewakers of the Molten Flow", description = "Of all Ragnaros' minions, the flamewakers appear to be the most devoted. Most of them dwell within this cave, preparing for another attack. Our foothold may be strong, but we will not tolerate any surprise attacks from these worms.\n\nNo, we will strike first.\n\nTear them apart, {name}.", sourceObjective = "Slay 8 Flamewakers within the Molten Flow.", completion = "I like the way you work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29265] = { id = 29265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Flowers", description = "My fellow druid, Choluna, has asked us to collect any specimens of plant life that we might find here in the Firelands...\n\n...I don't know whose idea it was to bring scholars to a warfront.\n\nNevertheless, you will already be in the cave - killing things - so be on the lookout for anything growing out of the ground.", sourceObjective = "Obtain 5 Luciferns.", progress = "They could be growing anywhere. Keep your eyes open.", completion = "These things never cease to amaze me. Whether they're actual plants, or just delicate stone formations, the fact that they can grow in such hostile conditions astounds me.\n\nI'll have these sent to Avrilla for analysis right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[29267] = { id = 29267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Good Will Come", description = "So much violence, so much death.  Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it.\n\nWill you take a pause from the violence to help care for a panther cub?", sourceObjective = "The panther cub looks at you with a look in its eyes that says, \"Will you be my new dad?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29268] = { id = 29268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Good Will Come", description = "So much violence, so much death.  Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it.\n\nWill you take a break from the violence and help care for a panther cub?", sourceObjective = "Care for the panther cub, after all, you did kill it's mother.", completion = "The panther cub looks at you with a look in its eyes that says, \"Will you be my new dad?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29269] = { id = 29269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At One", description = "I was charged with her protection, yet it was she who sacrificed herself for my sake.\n\nI cannot bear to lose her, {name}. I must make a solemn request of you.\n\nNever has a mortal borne the essence of a true dragon, but with your permission I would make an exception.\n\nPlease, while there is life in her, will you allow me to bind Tarecgosa to you?", sourceObjective = "Speak to Kalecgos to agree to his proposition.", sourceObjectiveStatus = "unverified-source-field" }
quests[29270] = { id = 29270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Grows Short", description = "Tarecgosa is bound to you, {name}, but only temporarily. An aspect's power is required to permanently seal her essence.\n\nMalygos's successor will not be chosen until Azeroth's moons next eclipse, and the bond you share will not last until then.\n\nFortunately, there is a way to buy us the time we need. Powerful elements exist that can extend the ritual's effects. Some of these can be found in the Plane of Fire, with which you've become familiar.\n\nObtain them, {class}, and sustain Tarecgosa until the eclipse.", sourceObjective = "Collect 1000 Seething Cinders from the Firelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[29271] = { id = 29271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound for Warmer Weather", description = "We should be okay here for now, and they have need of you in the Firelands. You should go through the portal and help them out.", sourceObjective = "Speak to General Taldris Moonfall at Malfurion's Breach on the Molten Front.", sourceObjectiveStatus = "unverified-source-field" }
quests[29272] = { id = 29272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need... Water... Badly...", description = "Need... water... badly...", sourceObjective = "Bring Anren Shadowseeker to the entrance of the Molten Front.", completion = "You! You're the one who saved Anren. My best friend, Anren.\n\nWe got separated in that cave. I didn't know what to do without Anren.\n\nYou are a resourceful {class}. We may call upon you later to assist us in our reconnaissance missions. With your help, Anren and I might no longer face the terrifying risk of being separated from one another.", sourceObjectiveStatus = "unverified-source-field" }
quests[29273] = { id = 29273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Hot", description = "The fire hawks of Fireplume Peak can withstand incredible temperatures. While you'll often find them circling the skies above, they're also known to swim in molten lava.\n\nIsn't that right, Anren?\n\nWe'd like to know just how hot that lava can get. Fireplume Peak has three large lava pools. Use this to measure the temperature of each.", sourceObjective = "Use Tholo's Thermometer to measure the temperature of the three large lava pools on Fireplume Peak.", completion = "These results will go a long way to help us understand the fire hawks, and - more importantly - Alysrazor, their new, fiery queen.\n\nTholo and I are thankful that you've been helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[29274] = { id = 29274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hounds of Shannox", description = "On the Firelands' largest island, our troops have been having trouble against Shannox, the flamewaker hunter. Not only does he have impeccable aim, but he keeps trained hounds that give our troops no end of trouble.\n\nTholo, in all his wisdom, thinks it would be a good idea to study the biology of these hounds. I, of course, agree with Tholo.\n\nYou will find several hounds in the Molten Flow, beneath the Furnace. We will need their ashes to study.", sourceObjective = "Obtain 6 small piles of Houndbone Ash.", progress = "Any information we can get will be instrumental in helping our men defeat Shannox.", completion = "This ash may seem indistinguishable from any other type of ash you find on this forsaken island, but trust me... you have found the right stuff.\n\nWe will have it analyzed immediately.\n\nReturn again soon. While I do enjoy spending time with Anren, we also appreciate your company, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29275] = { id = 29275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fandral's Methods", description = "The Druids of the Flame... an order of druids that, up until a few weeks ago, Tholo and I had never even heard of. Now, under the leadership of Fandral Staghelm, they threaten our mission's success with their mastery of fire.\n\nIt would appear that they store some supplies in the Igneous Depths, to the northeast. Perhaps, if we can get some of those supplies, we will have more luck when we take the fight to Fandral.", sourceObjective = "Obtain a Flame Druid Staff, a Flame Druid Spellbook, a Flame Druid Reagent Pouch, and a Flame Druid Idol.", progress = "Trust me - whatever information we can gather here will go far to helping us understand the source of Fandral's powers.", completion = "Anren, look what {name} found! This is exactly what we needed!\n\nIt will take us some time to look through these supplies. For now, you have our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[29276] = { id = 29276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flame Spider Queen", description = "The Widow's Clutch, to the northeast, is named after Beth'tilac, the enormous queen of the flame spiders. Her webs and her poison are a nagging threat to our main offensive force.\n\nWe believe that if we study the flame spiders here on the Molten Front, we can use that information to find success against Beth'tilac. Use whatever methods you can to gather their venom and their web fluid, then return to my trusted friend Anren.", sourceObjective = "Obtain 8 samples of Flame Venom and 8 samples of Searing Web Fluid.", progress = "Be careful with those fluids, {name}. We don't want them spilling anywhere.", completion = "You are an asset to our cause, {name}. Tholo and I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29278] = { id = 29278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Living Obsidium", description = "Have you seen those fireballs falling out of the sky? I saw one crash in the fields to the north, and the rock that landed was made of pure Living Obsidium!\n\nI can use the material to craft ultra-sturdy heat proof armor and weapons for our troops. Can you bring me a lode?\n\nGo to the Magma Springs and touch one of the magnetic stones. Just watch where you're standing when the rain of fire hits, and gather up the rocks before they crumble from the impact.", sourceObjective = "Retrieve 10 Obsidium Meteorites.", progress = "How's it going? Found any meteorites yet?", completion = "Fantastic! Now ah kin get ta work.", sourceObjectiveStatus = "unverified-source-field" }
quests[29279] = { id = 29279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling the Moonwell", description = "We've constructed this moonwell, but it serves little purpose until it is filled with the sacred waters of the Well of Eternity.\n\nWith an active moonwell, we would be able to bless our food stores, and we may also be able to use the blessing to offer you some protection from fire as well.\n\nWhen you've obtained enough marks, speak to Matoclaw at the Sanctuary of Malorne. She'll be able to secure transport of the sacred waters.", sourceObjective = "Obtain 125 Marks of the World Tree.", progress = "How can I be of aid, {name}?", completion = "Of course. I will see to it that the sacred waters are transported through the portal right away.\n\nThank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29280] = { id = 29280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nourishing Waters", description = "I have dispatched the sacred moonwell waters to Malfurion's Breach, as you requested. Ayla is well trained in tending to them. You should return to her and see the boons she weaves for you there.", sourceObjective = "Speak to Ayla Shadowstorm at Malfurion's Breach.", completion = "You will be pleased to know that the waters arrived safely. With the moonwell filled, and the shade of the Sentinel Tree upon us, I can almost forget we're in the Firelands for moments at a time.\n\nI've spread the moonwell's blessing upon these trees and bushes. Take the fruit with you before you venture out. It is more refreshing than you can possibly imagine.", sourceObjectiveStatus = "unverified-source-field" }
quests[29281] = { id = 29281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Armaments", description = "These druids be lackin' the tools ta properly handle the job out 'ere. I got meself a buddy back at day ol' stag shrine through the portal though. If we were ta be gettin' reunited, we'd sure have some real toys ta use against ol' Ragboy and 'is cronies.\n\nTake some of dem mark things an' go find Matoclaw. Ask her fer Ricket. We need'r here so we can be causin' some real trouble.", sourceObjective = "Obtain 125 Marks of the World Tree.", progress = "Yes, {name}?", completion = "I was wondering if those two would come in handy. They've seemed quite out of place ever since they arrived.\n\nI saw Ricket around here just a moment ago. I'll gladly send her back through the portal with you. She's less likely to be blowing up any local plant life on that side of things anyway.\n\nLet's see... where is she...", sourceObjectiveStatus = "unverified-source-field" }
quests[29282] = { id = 29282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well Armed", description = "Ricket should be at Malfurion's Breach with Damek, as you requested. I'm not sure you fully know what you're getting into with those two though.\n\nSpeaking of which, you should probably go check on them... make sure they haven't managed to blow up the Sentinel Tree itself. As long as you keep them busy with the elementals, the chances of \"accidents\" at the breach should lessen dramatically.", sourceObjective = "Speak to Ricket at Malfurion's Breach.", completion = "Hey you! Good to see you again!\n\nI'm settled in good and fine, actually! It's good to be with good old Damek again. I never thought I'd be mixing with a dwarf so well, but he and I, we've got like minds on all the important stuff.\n\nYou go do your thing. Don't be worrying about us. If we cook up any good toys for you, we'll be sure to let ya know!", sourceObjectiveStatus = "unverified-source-field" }
quests[29283] = { id = 29283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling the Ancients", description = "The ancients await in Hyjal. The Firelands will prove a dangerous place for them considering their... composition, but their strength will be of great use to us if we are to face any of Ragnaros' lieutenants.\n\nGather your marks, and seek out Elderlimb at the Sanctuary of Malorne. If they are to march with us, he would be the one leading them through the portal.", sourceObjective = "Obtain 125 Marks of the World Tree.", progress = "Greetings to you, young one.", completion = "I understand. We are prepared. We shall join the march and meet you on the far side of the portal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29284] = { id = 29284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid of the Ancients", description = "The ancients have seen the value of your wisdom, and have set root at Malfurion's Breach. You should seek out Elderlimb. I am certain he would like to hear from you.", sourceObjective = "Speak to Elderlimb at Malfurion's Breach.", completion = "You chose a wise time to call upon us, {class}. I was concerned for our ability to stand against the elements in this realm, but the protection of the Sentinel Tree has proven far more than sufficient shelter.\n\nWe will do anything we can to aid your efforts here. Witherbranch has met with your other allies and is discussing a way to corner some of Ragnaros' lieutenants. You should speak with them when the time comes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29285] = { id = 29285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alignment", description = "The time of choosing has arrived, {name}.\n\nWhile only members of the blue dragonflight may attend, Tarecgosa's binding makes your presence requisite.\n\nI must ask that you take on her form and vote on her behalf.\n\nDo not tarry. The moment of the eclipse draws near....", sourceObjective = "Accompany Kalecgos to the blue dragon council.\n\nSpeak to Kalecgos in Coldarra when ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[29287] = { id = 29287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peaked Interest", description = "These fire hawks are beings of fire, but they exhibit much of the same behavior that we've seen in birds back home. It makes me wonder from where they originate.\n\nBack to the point - I think we might be able to train them. Domesticate them if you will. Use them against our enemies.\n\nI'd like you to retrieve one of their eggs from the top of Fireplume Peak. If you can bring it back to me safely, I will see to the rest.", sourceObjective = "Retrieve a Fire Hawk Egg from the top of Fireplume Peak.", progress = "Were you able to recover an egg?", completion = "This will do perfectly! Come see me again in a day or two and we'll see how things have progressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[29288] = { id = 29288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starting Young", description = "Our scouts are bringing back reports of fire hawk hatchlings all over the peak... their eggs must have hatched very recently. Better yet, it seems that they're extremely docile.\n\nI know it may sound a strange and perhaps unsavory request, but if you were able to bring some of those hatchlings back to me, I might be able to train them to aid us in our war efforts.\n\nAre you willing?", sourceObjective = "Recover 5 Fire Hawk Hatchlings.", progress = "I can't make up my mind on how to regard these creatures. They act much like other avians, but they are very obviously native to this fiery place.\n\nI wonder why Ragnaros and his minions have not made attempts to rally them against us...", completion = "They look to have singed your gloves a bit, but I don't see any damage otherwise. Well done, {class}.\n\nCome by again within the next few days to see how the training has gone.", sourceObjectiveStatus = "unverified-source-field" }
quests[29289] = { id = 29289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mother's Malice", description = "Unsurprisingly, their matriarch has taken offense to us taking her young to train for our own uses. It's understandable... and a bit tragic actually. We are very much the villains in this exchange.\n\nNow is not the time for such thoughts. These creatures are beings of fire, and on more than one occasion, they've claimed the lives of our kin. With their matriarch angered, the danger has grown immensely.\n\nI need someone to quiet her rage, and I fear you may be the most capable.", sourceObjective = "Defeat the Fire Hawk Matriarch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29290] = { id = 29290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire in the Skies", description = "Look at that! It's incredible! Born less than two days ago and already full grown. Sadly, I suspect their life cycle is similarly short, so we'll have to take advantage of any time we have.\n\nHis training went remarkably well. I want you to be the one to take him out and unleash him on the bulk of the enemy forces gathered near Ragnaros' keep.\n\nShow no mercy, {race}.", sourceObjective = "Use the Trained Fire Hawk to kill 100 of the Flamewaker Salamanders, 40 of the Cinderweb Spiders, and 3 of the Molten Lords that are amassing in the Firelands.", progress = "Some of our most capable forces are poised to strike at Ragnaros himself. If these attacks go well, we may be able to give them the opportunity they need.", completion = "I take it your assault was a success! Brilliant. This could be a key moment in opening up Ragnaros' defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[29291] = { id = 29291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straight Chuting" }
quests[29292] = { id = 29292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hawk Fire" }
quests[29293] = { id = 29293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singed Wings", description = "Many of our Storm Crows have gone ahead to scout the peak and attempt to retrieve some of the fire hawk eggs, but to very little success I'm afraid. The thermals make it nearly impossible to fly safely, and the fire hawks aren't exactly friendly either.\n\nI need you to head over there and rescue any druids that you can. I've got splints, bandages, burn salves, smelling salts... anything you'll need to get them back on their feet, assuming they're still alive. Please hurry and help anyone you can find.", sourceObjective = "Rescue 5 Injured Druids of the Talon on Fireplume Peak.", progress = "There must be more of them alive over there... it's just a matter of finding them.", completion = "Several of our brothers and sisters passed by while returning to the safety of the Sentinel Tree. You did very well out there, {name}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29294] = { id = 29294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animate Embers", description = "Several of our scouts have reported seeing what seemed to be living flames skittering around the surfaces of Fireplume Peak.\n\nIf the reports are accurate, we need these for study immediately. We've yet to fully understand where all of the attacking elementals come from, and these could well lend us significant insight.", sourceObjective = "Retrieve 6 Animate Embers.", sourceObjectiveStatus = "unverified-source-field" }
quests[29295] = { id = 29295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bigger They Are", description = "You're not going to take on fiery behemoths wearing THAT, are you? If you aren't wearing my obsidium crafted goods, you're going to burn right up! And even if you are, you can never have enough of the good stuff.\n\nLook <brother/sister>, I can craft you the best armor that gold can buy, but I need pure, unsmelted Living Obsidium first.\n\nThe Obsidium Punishers on Fireplume Peak are literally made of the stuff. Go kill them and gather their pieces.", sourceObjective = "Collect 10 Living Obsidium from the Obsidium Punishers on Fireplume Peak.", progress = "Did you bring me the goods?", completion = "This'll do. Nice work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29296] = { id = 29296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territorial Birds", description = "The fire hawks are upset by our continued presence. They're getting extremely hostile, and not just in the usual territorial ways. I worry that if we leave them unchecked, they will soon be joining the assault on our tree, and I'm not sure we're capable of handling that.\n\nGo across the way to Fireplume Peak and do what you have to to keep them in check. I'm far more concerned with our safety right now than theirs, so be decisive about it.", sourceObjective = "Slay 5 Fire Hawks.", completion = "Well done, {name}. It's good to know I can count on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29297] = { id = 29297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bye Bye Burdy", description = "Staghelm's druids are putting up a fierce fight at Wildflame Point to the northeast.\n\nThe druids fly above us in fire crow form, then strike when we least expect it. Worst part is, they know exactly how to stay out of our reach!\n\nWe would be totally helpless, except Damek lent me his trusty harpoon. He says these weapons will fly straight and true even in this super dense air.\n\nTake the dwarf's weapon and shoot some birds out of the sky!", sourceObjective = "Kill 3 Druids of the Flame, while in Fire Crow form, with the Burd Sticker.", completion = "Those blasted burds are dead? Good riddance!", sourceObjectiveStatus = "unverified-source-field" }
quests[29298] = { id = 29298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smoke-Stained Locket", description = "This locket has a few small leaf-shaped carvings etched into its face, but any other details have been rubbed away with time, or burned away with fire. It appears to be druidic in nature.\n\nMost druids pass through Moonglade during their training. If anybody can help you decipher where this locket came from, it would be Rabine Saturna of Nighthaven.", sourceObjective = "Bring the Smoke-Stained Locket to Rabine Saturna at Nighthaven in Moonglade.", progress = "Yes, young {race}?", completion = "What have we here? A necklace? No, a locket...\n\nOh, my...", sourceObjectiveStatus = "unverified-source-field" }
quests[29299] = { id = 29299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Like It Hot", description = "I've been making progress in my research, {name}. Based on what we've witnessed in the local flora, it's quite possible that your Lasher also accepts superheated liquids as a principal source of nutrition.\n\nI'd like you to help me with a little experiment. The Emberspit Scorpions that inhabit the Magma Springs to the north spew out burning pools of fire during combat.\n\nTake the Lasher and observe his reaction to the scorpions' Ember Pools.", sourceObjective = "Observe the Crimson Lasher drinking from 6 Ember Pools. Ember Pools are created by fighting Emberspit Scorpions.", progress = "I would have gone to observe the Lasher myself, but the battle is just so...violent!", completion = "Did it work? So my theory was correct?", sourceObjectiveStatus = "unverified-source-field" }
quests[29302] = { id = 29302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking the Secrets Within", description = "The initials seem to have worn off of this locket, but I can sense a power within it that suggests only one possible owner:\n\nLeyara, the Druid of the Flame.\n\nStand back, and we shall see what surprises this locket contains.", sourceObjective = "Witness the memories stored within the Smoke-Stained Locket.", completion = "If Leyara bore witness to the War of the Shifting Sands, then it seems likely she knew Fandral - and his late son, Valstann - far more closely than any of us suspected.\n\nIt would seem that your journey does not end here, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29303] = { id = 29303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tragedy and Family", description = "You were insightful to bring this locket to me, {name}. I am among the few who know where Valstann's body lays.\n\nYou can find his resting site in a small graveyard, southeast of Astranaar, in Ashenvale. Bring this locket to the site, and it may unlock more memories.\n\nFarewell, {name}, and good luck on your journey.", sourceObjective = "Bring the Smoke-Stained Locket to the Night Elf Grave near Astranaar in Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[29304] = { id = 29304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dogs of War", description = "Our forces are falling beneath an unleashed monstrosity - Charhounds from the molten depths.\n\nThese dogs fear nothing and will not stop until their lust for blood is satisfied. Our forces are barely holding them back.\n\nGo join the defenders in the Ashen Fields or in the Molten Flow. Perhaps you can make a dent in their numbers.", sourceObjective = "Kill 5 Charhounds or Ancient Charhounds.", progress = "This war will be long and cruel. Do not weep for lost comrades. Save your energy for the enemy.", completion = "Good, {class}. The enemy may be tough, but you have proven today that you are tougher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29305] = { id = 29305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike at the Heart", description = "One of Ragnaros' Lieutenants has shown himself at Ragnaros' Reach, the walled area to our northeast.\n\nI hoped to send you as soon as you returned, but I suspect Witherbranch and some of our forces have already joined the fight by now. You should hurry.\n\nYou should be able to drop down the cliff wall right here and reach them quickly.", sourceObjective = "Kill the Lieutenant of Flame.", progress = "Today we cripple their war effort.", completion = "Very well done, {name}! This should delay them significantly.\n\nIf we keep this up, we can easily push the fight back to Ragnaros himself.", sourceObjectiveStatus = "unverified-source-field" }
quests[29307] = { id = 29307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Flame", description = "You are the first mortal to witness a dragon council, {name}, and among the only beings in Azeroth to take part in the choosing of an Aspect.\n\nMy ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home.\n\nI would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros.\n\nWhen next we meet, I will be able to suitably thank you for all that you have done.", sourceObjective = "Empower the Runestaff of Nordrassil with 250 Smouldering Essences and obtain the Heart of Flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[29308] = { id = 29308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Flame", description = "You are the first mortal to witness a dragon council, {name}, and among the only beings in Azeroth to take part in the choosing of an Aspect.\n\nMy ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home.\n\nI would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros.\n\nWhen next we meet, I will be able to suitably thank you for all that you have done.", sourceObjective = "Empower the Runestaff of Nordrassil with 250 Soul Flame Essences and obtain the Heart of Flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[29309] = { id = 29309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stuff of Legends", description = "It is an honor to make your acquaintance, {race}.\n\nYour deeds echo in the ears of Azeroth's creatures, mortal and immortal alike.\n\nI shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon.\n\nThe ceremony is to begin shortly. I have been appointed to escort you there when you are ready.", sourceObjective = "Speak to Hallegosa.", sourceObjectiveStatus = "unverified-source-field" }
quests[29310] = { id = 29310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tipping Point", description = "On the day when Leyara attacked Hamuul, she was waiting near some ruins in Hyjal, northwest of the Regrowth. She acted strangely at the time: calm, silent, and staring off into the distance. Perhaps that location is of some importance to her.\n\nThe locket might react if brought to that location.", sourceObjective = "Bring the Smoke-Stained Locket to the Small Gravestone at Leyara's Sorrow in Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29311] = { id = 29311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rest is History", description = "In her memories, Leyara spoke of Malfurion. The tragedies of her past - at least, in her opinion - are largely due to his actions.\n\nMalfurion must remember Leyara from before she became a Druid of the Flame. You resolve to bring the locket to him in the Firelands. Hopefully he can answer any remaining questions.", sourceObjective = "Bring the Smoke-Stained Locket to Malfurion in the Molten Front.\n\nProvided item:", completion = "Yes, I knew Leyara, and I was aware of her anger even before she joined the Druids of the Flame. She was a promising young druid, once. Unfortunately, the bonds of family are often stronger than the power of reason, and ultimately, she chose to follow Fandral down his treacherous path.\n\nYou should keep this locket, {name}. May it remind you that each of us walks our own path through life... and that some paths are easier than others.", sourceObjectiveStatus = "unverified-source-field" }
quests[29312] = { id = 29312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stuff of Legends", description = "It is an honor to make your acquaintance, {race}.\n\nYour deeds echo in the ears of Azeroth's creatures, mortal and immortal alike.\n\nI shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon.\n\nThe ceremony is to begin shortly. I have been appointed to escort you there when you are ready.", sourceObjective = "Speak to Hallegosa.", sourceObjectiveStatus = "unverified-source-field" }
quests[29313] = { id = 29313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret to Perfect Kimchi", description = "My family has been making the best kimchi in Darnassus for generations, {name}. The secret is something simple, but it makes all the difference.\n\nWe bury the jars in the ground until it's ready to serve and my latest batch has just reached that point. You can find the jars buried in earthen mounds all over the city. Would you help me gather them while the contents are just right?", sourceObjective = "Find 8 Buried Kimchi Jars in Darnassus.", progress = "Were you able to find the jars?", completion = "Thank you, {name}. There's no way I could've found them all in time and it would be a shame to miss out on so much good kimchi!", sourceObjectiveStatus = "unverified-source-field" }
quests[29314] = { id = 29314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remembering the Ancestors", description = "The living are not the only ones who require sustenance. One of my duties is to prepare the rice cakes that are left for the ancestors. Normally, my senior apprentice has the honor of taking the cakes to the Temple of the Moon for blessing and then presenting them to the ancestors. Since she is out of the city today, would you mind performing the duty in her place?", sourceObjective = "Collect the Blessed Rice Cakes from the Temple of the Moon.", progress = "This is the shrine the trainer mentioned.", completion = "<You lay out the rice cakes around the shrine, which begins to glow softly. A faint sense of approval washes over you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29315] = { id = 29315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungus Among Us", description = "Some chefs complain that our beloved Undercity doesn't boast the ingredients to create truly fine fare.\n\nSuch mewling little cretins. Delicious delights abound!\n\nGather some of the rank, slimy Sewer Caps growing in Undercity's northwest sewer line and return them to me.", sourceObjective = "Obtain 12 Sewer Caps. Deliver the fungus to Eunice Burch in Undercity.", progress = "Did you find enough Sewer Caps?", completion = "These smell absolutely wretched. Perfect!", sourceObjectiveStatus = "unverified-source-field" }
quests[29316] = { id = 29316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Basics", description = "There are certain things that everyone needs, from the basic household cook to the master chef. One of the city's most important staples is rice flour. Most families keep at least one basket of rice in their houses and the residents of the Craftsmen's Terrace and Tradesmen's Terrace are no different.\n\nI often ask my students to help with the task of pounding rice into flour since it's good practice and an endless task. Why don't you give it a try?", sourceObjective = "Help the inhabitants of the Craftsmen's Terrace and Tradesmen's Terrace make rice flour by pounding the contents of Rice Baskets.", progress = "Have you practiced making rice flour?", completion = "It takes a lot of effort to ensure that there's enough flour for everyone's needs. Thank you for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29317] = { id = 29317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Head", description = "There was an... incident... with an orc guard and one of Master Apothecary Faranell's abominations.\n\nApparently, the Kor'kron Overseer chopped its head clean off and kicked it into the slime.\n\nFaranell's apprentices searched for hours but they can't find the thing. Care to try fishing it up? I'm sure the old fellow'd be grateful.", sourceObjective = "Armand Cromwell wants you to fish up a Severed Abomination Head in Undercity for Master Apothecary Faranell.", progress = "You haven't by any chance come across a severed abomination head, have you...?", completion = "Ah! THERE it is! How ever did you find it?\n\nWell, no matter. My apprentices weren't able to recover the head despite hours splashing about in the slime, though they DID recover this bag of shiny things... perhaps you've a use for what's inside?\n\nMy thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[29318] = { id = 29318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ribs for the Sentinels", description = "One of my responsibilities is to feed the sentinels of Darnassus while they're on duty. It's a time-consuming task, but one I'm happy to undertake. It's also a great way to practice your skills. Would you mind helping me with today's meal? Simply take these ribs, cook them near a stove or fire, and distribute them to sentinels throughout the city.", sourceObjective = "Use the Uncooked Ribs near a stove or campfire to cook them and then use them to feed 5 Darnassus Sentinels.", progress = "The sentinels train hard to keep Darnassus safe and they have big appetites!", completion = "Feeding all those sentinels is much easier with your help. Nobody had to wait in line for their meal this time.", sourceObjectiveStatus = "unverified-source-field" }
quests[29319] = { id = 29319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tadpole Terror", description = "Some of our apothecaries took to dumping their more volatile waste chemicals into Stillwater Pond and... well, let's just say that no one wants to know how big mutant flesh-eating toads can grow.\n\nWould you consider fishing up some giant flesh-eating tadpoles before it gets to that? Just don't try to handle them with your bare hands.", sourceObjective = "Armand Cromwell in Undercity wants you to bring him 8 Giant Flesh-Eating Tadpoles.", progress = "Catch any mutant tadpoles? Don't try to handle them with your bare hands.", completion = "Excellent work, {name}. I'll see that these are, ah, disposed of immediately.\n\nAfter all, what would our fine apothecaries want with an army of monstrous, poison-spitting, flesh-eating super-toads?", sourceObjectiveStatus = "unverified-source-field" }
quests[29320] = { id = 29320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Pike?", description = "You've fished in Brightwater Lake, yes?\n\nThe prize catch there is one of the lake's massive corpse-fed pikes. However, they only bite on a very specific type of bait... corpse worms.\n\nSearch the graves in the courtyard up top and you should find some.", sourceObjective = "Dig up a Corpse Worm in the Ruins of Lordaeron courtyard and use it as bait to catch a Corpse-Fed Pike. Corpse-Fed Pike can be fished up in Brightwater Lake, northeast of Undercity.", progress = "Catch that pike, yet?", completion = "That's a fine, fat pike, {name}.  Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[29321] = { id = 29321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Happy as a Clam Digger", description = "It seems like everyone I know loves clams, but I can't stand them! They're smelly and slimy, and harvesting them means digging through mud. Give me a fishing pole and some bait any day.\n\nStill, I want to surprise my brother with a bucket of fresh clams. I'd reward you if you were willing to gather those clams for me.\n\nJust go through the portal to Rut'theran Village and look for the clams in the shallows near the shore.", sourceObjective = "Gather 10 Teldrassil Clams from the shores near Rut'theran Village.", progress = "Did you find enough clams?", completion = "Yuck, they're so gross-looking, but they're my brother's favorite. Thanks for sparing me from that messy job!", sourceObjectiveStatus = "unverified-source-field" }
quests[29322] = { id = 29322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Slime", description = "It takes a special sort of fisherman to reap the bounty of Undercity's burbling slime troughs. Think you can handle gathering some of the squirming, sentient slime mold slithering about down there?\n\nYou can try to fish them up, but they're wily; you might be better off just diving into the ooze and grabbing them.\n\nRemember, they're only useful alive and intact... who'd want to eat a dead slime mold?! Disgusting.", sourceObjective = "Collect 10 Squirming Slime Molds. Deliver them to Armand Cromwell in Undercity.", progress = "Difficult to catch, aren't they?", completion = "These slimes look perfect.  I will send these along to Eunice for preparation, thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29323] = { id = 29323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up", description = "We've used up most of our food stores in taking care of refugees and feeding those whose homes and livelihoods were destroyed. If we don't replenish our stores, we'll all be in danger next time there's a bad storm or a Horde invasion.\n\nPerhaps you'd be willing to help me build up our stock of lake whitefish. You can catch it anywhere in Darnassus, and once it's dried, it'll keep until it's needed.", sourceObjective = "Catch 5 Lake Whitefish by fishing in Darnassus.", progress = "If all of our fishermen pitch in, it won't take long to rebuild our supplies.", completion = "These are beautiful! Thank you, {name}. I'll set them out to dry.", sourceObjectiveStatus = "unverified-source-field" }
quests[29324] = { id = 29324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sister's Pendant", description = "Have you met Sister Aquinne? She and I grew up together in Dolanaar, and she recently came to the city to study at the Temple of the Moon. We decided to go for a boat ride, but the clumsy oarsman managed to capsize the craft!\n\nWhen we got back to the shore, Aquinne's moon pendant was missing. The lakes in Darnassus are full of giant catfish who will gobble up anything shiny!\n\nI've been catching them nonstop, hoping to find the one with her pendant. I don't suppose you want to help?", sourceObjective = "Retrieve Aquinne's Moon Pendant from the belly of a Giant Catfish. You should be able to catch them anywhere you can fish in Darnassus.", progress = "Have you had any luck finding Aquinne's missing pendant? I must've caught fifty of those monsters and I have nothing to show for it!", completion = "<Astaia takes the pendant from you.>\n\nUnderneath all the slime and tarnish, I think this is it! Aquinne will be so happy to have this back... after a thorough cleaning, of course. I can't thank you enough, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29325] = { id = 29325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slippery Snack", description = "Have you ever eaten octopus meat? It takes some getting used to, but it's my favorite! I even know some people who like to eat the whole thing while it's alive!\n\nI don't plan on trying that anytime soon, but I am out of fresh octopi at the moment. Will you help me gather some more? They live in the shallow water off the shore near Rut'theran Village.", sourceObjective = "Gather 6 Baby Octopi from the shallow water near Rut'theran Village.", progress = "It's impossible to catch octopi with a fishing line, so you're just going to have to grab them!", completion = "These are going to be delicious, I can already tell! Thanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29326] = { id = 29326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nordrassil Summit", description = "Hello, {class}! My brothers and sisters of the Earthen Ring have spoken well of your deeds in the wake of the Cataclysm. But much remains to be done if we are to heal this broken world.\n\nWalk with me, friend. Preparations for a ceremony are underway, a ritual that I hope will be a turning point in our battle against the Twilight's Hammer.\n\nWhen all is done, you will be able to spread the word about our triumph here.", sourceObjective = "Speak with Thrall under the World Tree in Mount Hyjal and witness the Earthen Ring ceremony.", sourceObjectiveStatus = "unverified-source-field" }
quests[29327] = { id = 29327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Bonds: Doubt", description = "I do know the one you seek... but I do not know if it is wise for you to follow him. He has cast himself into the cyclone. The winds now tear at his body and mind, leaving nothing but shreds of flesh and doubt.\n\nChasing after him would only expose you to the same fate. The wind's edge leaves nothing uncut.\n\nYou have been warned. Now what will you do?", sourceObjective = "Speak with Cyclonas to secure passage to Thrall. Then, fight the wind elementals that torment him until he is freed.", sourceObjectiveStatus = "unverified-source-field" }
quests[29328] = { id = 29328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Bonds: Desire", description = "Once again, {class}, I cannot do this without your help. I will try to quiet this tempest, but you will need to fight back the unstable elementals that whirl around it. Only then can we free Go'el!", sourceObjective = "Slay the Tides of Longing and Vortexes of Longing near the Abyssal Breach until Thrall is free of their grasp.", sourceObjectiveStatus = "unverified-source-field" }
quests[29329] = { id = 29329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Bonds: Patience", description = "With the Stonemother's blessing, I can take us to where Go'el is being held.\n\nWe must be careful. The Twilight's Hammer has agents all around. You help me hold them off while I attempt to get through to Go'el!\n\nSpeak with me when you are ready, and I will take you to him.", sourceObjective = "Speak with Aggra when you are ready to help Thrall. Then defeat the Elements of Patience and Corestones of Patience that are holding him captive.", sourceObjectiveStatus = "unverified-source-field" }
quests[29330] = { id = 29330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Bonds: Fury", description = "The totems, {name}! We need to activate them, or Go'el is lost!\n\nKill the elementals next to each of my totems, located around the edges of this plateau. Once all four totems are activated, we should be able to free the last piece of Go'el's soul!", sourceObjective = "Kill fire elementals next to Aggra's Air Totem, on the western edge of the plateau, until it activates. Then continue to Aggra's Water Totem, Aggra's Earth Totem, and Aggra's Fire Totem.", sourceObjectiveStatus = "unverified-source-field" }
quests[29331] = { id = 29331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Bonds: The Vow", description = "Before he passed through the portal to Mount Hyjal, Thrall asked you to follow him. There is something he would like you to witness.You will be able to choose one of these rewards:", sourceObjective = "Speak with Thrall at Nordrassil in Mount Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29332] = { id = 29332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lily, Oh Lily", description = "The lilies that grow around Stillwater Pond can be rendered down into a delightful broth.\n\nWell... by \"delightful,\" I mean \"won't immediately sicken any orc who drinks it.\"\n\nWhy don't you go gather some for me, hmmm? Just watch out for the giant flesh-eating tadpoles.", sourceObjective = "Obtain 10 Stillwater Lilies. Deliver the plants to Eunice Burch in Undercity.", progress = "Did you find enough Stillwater Lilies?", completion = "Ah, what a luscious batch of lilies. Bravo! I'll boil them down right away...", sourceObjectiveStatus = "unverified-source-field" }
quests[29333] = { id = 29333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escargot A Go-Go", description = "The orc guards are always grumbling about bland and moldering Undercity fare - as if it's OUR fault they can't get by on a diet of mushrooms and old corpses - so I think it's time they learn just the sort of exotic delights we can cook up when we've a mind to.\n\nGather some of the freshwater snails ambling about beneath Brightwater Lake and I'll show them what a true culinary master can create.", sourceObjective = "Collect 8 Brightwater Snails. Deliver them to Eunice Burch in Undercity.", progress = "Gather those freshwater snails, yet?", completion = "You must be quite the swimmer... all I can manage is the dead man's float.\n\nIn any case, excellent batch of snails you've gathered. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29334] = { id = 29334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roach Coach", description = "For all the grousing those Kor'kron Overseers do about Undercity food, there's ONE thing they'll eat in spades: My sister Audrey's Thrice-Spiced Crunchy Stew.\n\nIts popularity means she's always running low on ingredients. Could you gather some for her at the coach she sells them from?\n\nYou'll find traps all over the city; just take their contents to Audrey and she'll handle the rest!", sourceObjective = "Obtain 20 Plump Cockroaches. Deliver the insects to Chef Audrey in Undercity.", progress = "I call my little traps \"Cockroach Cabins.\"\n\nCockroaches check in, but they don't check out!", completion = "Oh, and just as I was nearly out. Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[29335] = { id = 29335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Slashing Winds", description = "{class}, I refuse to believe my Go'el is lost forever. His spirit has been scattered across the elemental planes. If even a part of him still exists, we can find him, but I will need your help.\n\nWe will start with the plane of air.\n\nSpeak to me and we will travel to the Vortex Pinnacle together. We must speak with an elemental, Cyclonas. He's capricious, but he sees everything in the realm of air. If my love is there, Cyclonas will know what's become of him.", sourceObjective = "Speak with Cyclonas on the Bluff of the South Wind in Uldum.", sourceObjectiveStatus = "unverified-source-field" }
quests[29336] = { id = 29336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Coaxing Tides", description = "Go'el must be in the plane of water... the Abyssal Maw itself! I shudder to imagine what fate awaits him there.\n\nFind the elemental, Hydrius, near the Abyssal Breach. He knows of Go'el and is sympathetic to our fight against Ragnaros. If anyone can help you there, it's him.\n\nI will meet you beneath the tides of Vashj'ir, {race}...", sourceObjective = "Speak with Hydrius at the Abyssal Breach in the Abyssal Depths of Vashj'ir.", sourceObjectiveStatus = "unverified-source-field" }
quests[29337] = { id = 29337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Constant Earth", description = "Time is short! My love lies in Deepholm. I will take us there when you are ready, and we will speak with Therazane the Stonemother.", sourceObjective = "Speak with Therazane at Therazane's Throne in Deepholm.\n\nAggra can teleport you to Therazane's Throne from the Abyssal Breach.", sourceObjectiveStatus = "unverified-source-field" }
quests[29338] = { id = 29338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Unrelenting Flame", description = "We must travel now to the Firelands. Within that realm, Go'el's burning spirit could become as terrible as Ragnaros himself! Prepare yourself, for we will be alone in a hostile world.\n\nSpeak with me when you are ready... and may the ancestors protect us!", sourceObjective = "Speak with Aggra on the Staidridge in Deepholm to secure passage to the Firelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[29339] = { id = 29339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29340] = { id = 29340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29341] = { id = 29341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29342] = { id = 29342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Water Fishing", description = "The best tastin' fish live in the cold waters o' Dun Morogh, {name}, an' don't let anyone else tell ye otherwise! Me favorite, an' the most popular one in Ironforge, is the arctic char, which only comes from our ancestral lands.\n\nI like tae think o' it as Ironforge's gift t' the world!\n\nWhy don't ye try yer hand at catchin' a few yerself? The best place tae find 'em is down in Helm's Bed Lake, in the eastern end o' Dun Morogh.", sourceObjective = "Catch 5 Arctic Char by fishing in Helm's Bed Lake in Dun Morogh.", progress = "Have ye tried to catch those char?", completion = "These are beautiful, {name}! I think ye've got the hang of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29343] = { id = 29343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One fer the Ages", description = "I'm sure by now ye've heard the tale o' Old Ironjaw, the most famous and elusive fish in the waters o' Ironforge's Forlorn Cavern. Well, in his many years, he's been responsible for the rise o' many young ironjaws. Don't let the name fool ye, {name}, these young'uns are every bit as clever as their dad, but somewhat lackin' in experience.\n\nWith skill an' patience, ye could probably catch one, an' when ye do, bring it to the museum in Ironforge's Library an' put it on display fer all to see!", sourceObjective = "Catch a Young Ironjaw in Ironforge's Forlorn Cavern and display it in the Library near the Empty Plaque.", progress = "Did ye catch one o' Ironjaw's offspring?", completion = "Well done, {name}! Maybe seein' yer catch will inspire more dwarves to take up fishin'!", sourceObjectiveStatus = "unverified-source-field" }
quests[29344] = { id = 29344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish fer Squirky", description = "Hae I introduced ye tae me pet, Squirky? I'm teachin' him tae fish all proper-like. Fer now, I've been feedin' him minnows fished from the pool in this cavern.\n\nMaybe ye'd like tae give it a try? Just cast yer lure in the pool over there and feed Squirky any minnows ye happen tae fish up. He'll love ye ferever!", sourceObjective = "Catch 3 Blind Minnows in the pool in the Forlorn Cavern and feed them to Squirky.", progress = "How's Squirky's lunch comin'?", completion = "Ye've done a good job. Squirky seems happy and I've had some time to make some new lures. Thank ye fer the help!", sourceObjectiveStatus = "unverified-source-field" }
quests[29345] = { id = 29345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pond Predators", description = "A well-meaning goblin visitor introduced Azshara snakeheads to our waters and now they're overrunning the pond.\n\nPlease, if you can catch some of these voracious predatory fish before they eat every smallfish and mud snapper in Thunder Bluff, I'd be terribly grateful.", sourceObjective = "Kah Mistrunner in Thunder Bluff wants 8 Azshara Snakehead fish from the Thunder Bluff pond.", progress = "Have you caught any Azshara snakeheads, yet?", completion = "Good work, {name}. It's up to all of Thunder Bluff's fishers to keep this vicious creature out of Mulgore's waters.", sourceObjectiveStatus = "unverified-source-field" }
quests[29346] = { id = 29346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring's the Thing", description = "One of the Forsaken from the Pools of Vision came to me and said he'd lost his ring to a blind cavefish in the waters there.\n\nOr perhaps it was his finger. It was hard to tell; his jaw did not move and his Orcish was no better than mine.\n\nIn any case, I thought it would be a kind gesture towards our unusual visitors to catch and gut cavefish until the ring - or finger - was found.\n\nWould you help?", sourceObjective = "Fish up a Blind Cavefish from the Pools of Vision in Thunder Bluff. Once you catch a cavefish, fillet it and check if it swallowed the ring.", progress = "You haven't seen a ring about, have you? I think one of the cavefish might have swallowed it...", completion = "You found my ring, did you? I'm most grateful.\n\nTo be honest, I've no idea why I keep the thing. I'm not even certain how I acquired it... I suppose I am simply a creature of habit.\n\nStill, as I said, I am grateful. Say... I found these things while searching for it myself. Perhaps they'd be of some use to you?", sourceObjectiveStatus = "unverified-source-field" }
quests[29347] = { id = 29347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Live Bait", description = "If ye've ever fished fer crayfish, ye know they respond best to live bait, an' the more bait, the better. Would ye like to test my new bait? Simply smear this on yerself an' hop into Helm's Bed Lake in eastern Dun Morogh.\n\nAfter ye've got the catch, take it to me friend, Cook Ghilm at Gol'Bolar Quarry, west of the lake. He's an expert at cookin' those oversized bugs!", sourceObjective = "Use Grimnur's Bait on yourself, then jump into Helm's Bed Lake in Dun Morogh.", progress = "Oh... this might hurt a wee bit.", completion = "These are beautiful, {name}! Grimnur's goin' tae be so proud when he hears about this!\n\nOh, he did say tae pass this along tae ye, if the scheme worked.", sourceObjectiveStatus = "unverified-source-field" }
quests[29348] = { id = 29348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Race to Restock", description = "Thunder Bluff's fishing pond is being overrun with voracious Azshara snakeheads; there are hardly any smallfish or mud snappers left.\n\nWe already have fishers trying to kill as many snakeheads as they can, but can you assist us in our restocking efforts?\n\nIf you could gather some fish from Stonebull Lake and bring them here to Thunder Bluff, I would be very grateful.", sourceObjective = "Kah Mistrunner in Thunder Bluff wants 2 Randy Smallfish and 2 Amorous Mud Snappers from Stonebull Lake in Mulgore.", progress = "Did you bring those fish from Stonebull Lake, yet?", completion = "Your help is much appreciated, {name}.\n\nHopefully these fish will go a long way towards restocking our fishing pond.", sourceObjectiveStatus = "unverified-source-field" }
quests[29349] = { id = 29349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craving Crayfish", description = "One of the great delicacies of Mulgore is the crayfish that dwell in our lakes and streams. They are particularly popular during weddings or the celebration of a birth.\n\nWould you help me catch some of these crafty crustaceans for the cooking pots of Thunder Bluff?\n\nYou can fish them up from Stonebull Lake, or simply dive in and grab them.", sourceObjective = "Kah Mistrunner in Thunder Bluff wants 10 Stonebull Crayfish from Stonebull Lake in Mulgore.", progress = "Crayfish are so tasty. Have you caught many?", completion = "Ah, so many crayfish!\n\nDid you fish these up? Or simply swim after them?\n\nWell, no matter. Excellent work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29350] = { id = 29350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gnomish Bait-o-Matic", description = "One o' the gnomish engineerin' trainers gave me a blueprint fer a fancy lure he says'll help me catch fish faster and keep 'em from gettin' away. The whole thing sounds a mite silly if ye ask me, but I'll try anythin' once.\n\nHere are the blueprints. Ye're going to need shiny baubles, which ye can buy from my assistant inside the buildin', a hair trigger ye can buy from an engineerin' supplier in Tinker Town, and a few rat traps from the Deeprun Tram.", sourceObjective = "Use the Bait-o-Matic Blueprint with 5 Shiny Baubles, a Hair Trigger, and 3 Rat Traps to create the Gnomish Bait-o-Matic.", progress = "How's that fancy new lure comin' along?", completion = "It doesn't look like anything I think a fish'd be interested in, but ye never know. Fish're strange creatures. Thanks fer givin' this a try, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29351] = { id = 29351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Round for the Guards", description = "The guards who defend Ironforge put their lives on the line against our many enemies, and it's up to us to take care of them.\n\nToday, their rations consist of two dwarven favorites, haggis and Ironforge pale ale. Would ye be so kind as to help me distribute them? That way, everyone gets his food in a timely manner and we can move on to other tasks.", sourceObjective = "Distribute the Ironforge Rations to 6 Ironforge Guards.", progress = "Did you distribute all the rations?", completion = "A full guard is a happy guard, as I always say. Thanks fer yer help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29352] = { id = 29352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fowl Shortage", description = "Oh, no, {name}, this is going to be a disaster if we don't find some chicken soon... Ye just cannae make cock-a-leekie soup without the chicken! It's not possible!\n\nThere's still time to make the soup and broth if ye can find some fresh chicken. Will ye help me? There are usually a few chickens running around outside the front entrance to the city. If ye can get yer hands on, say, six o' them, that should save me soup.", sourceObjective = "Collect 6 Dun Morogh Chickens near the entrance to Ironforge.", progress = "The chickens, {name}, do ye have them or not?", completion = "Aye, that's exactly what I needed. Ye have me thanks, {name}, and me apologies fer bein' so brusque earlier. I just cannae stand the thought of not gettin' a meal finished on time.", sourceObjectiveStatus = "unverified-source-field" }
quests[29353] = { id = 29353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keepin' the Haggis Flowin'", description = "The haggis must flow. Aye, it's a figure o' speech, for haggis'll ne'er flow! Ye dinnae want to know what'll happen if the people o' Ironforge don't get their haggis.\n\nI'm working on the next batch, but I'm still missing a couple of ingredients.\n\nSognar Cliffbeard is the meat vendor in the Military Ward, an' he'll sell you the big bag o' sheep innards I need. Ye can buy mild spices from any cooking supplier and ye can find sacks o' oatmeal in any inn or among the supplies  in the city.", sourceObjective = "Obtain a Bag o' Sheep Innards, 5 packets of Mild Spices, and 4 Sacks of Oatmeal.", progress = "Do ye have those ingredients?", completion = "Ye got them all? Wonderful! I'll get started right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[29354] = { id = 29354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shiny Baubles", description = "One of a fisher's most simple and effective tools is the shiny bauble; affixed to a line, even the most novice angler has a chance at a catch.\n\nWith all the fishing going on of late, though, Thunder Bluff is in woefully short supply!\n\nMight I ask you to collect shiny stones from around the base of the central rise? Bring them to Nahari Cloudchaser so that she might craft more shiny baubles with them.", sourceObjective = "Nahari Cloudchaser in Thunder Bluff wants 20 Shiny Stones from around the central rise's base.", progress = "Did you happen to bring me any shiny stones?", completion = "My, those are some very lovely stones! They'll make perfect shiny baubles, thank you.\n\nHere... Kah told me you'd be by with the stones, and to give this to you upon your arrival.", sourceObjectiveStatus = "unverified-source-field" }
quests[29355] = { id = 29355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Enough Spice Bread", description = "It might seem like a basic thing, {name}, but spice bread is a longtime favorite in Ironforge. Some days, I have trouble keeping up!\n\nWould ye like to cook some to practice yer skills an' help meet the demand? Ye can buy all the ingredients ye'll need from me brother, Emrul Riknussun, who is downstairs.", sourceObjective = "Make or obtain 10 slices of Spice Bread.", progress = "How's that spice bread?", completion = "That bread looks delicious. Thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29356] = { id = 29356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Need to Cask a Favor", description = "My stocks o' IPA, that's Ironforge Pale Ale for ye novices, are gettin' low. Luckily, the brewery isn't too far away an' they should have a new cask o' Drugan's IPA waitin' fer us. That Drugan's a genius of a brewer, I tell ye.\n\nI won't be able to get down to Kharanos meself today, but perhaps ye can dash down there, pick up the new cask an' run it back 'ere? What d'ye say?", sourceObjective = "Pick up the Cask of Drugan's IPA outside the brewery in Kharanos and run it back to Ironforge.", progress = "Well, did ye get the cask or not?", completion = "Ah, well done! I tell ye, that Drugan's a true polymath -- explorer, historian, brewer -- is there anythin' that man hasn't mastered?", sourceObjectiveStatus = "unverified-source-field" }
quests[29357] = { id = 29357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spice Bread Aplenty", description = "Isn't it amazing how something as simple as spice bread is used every day in Darnassus? When I'm not seeing to my other responsibilities, I like to bake spice bread to hone my skills as a cook and practice my technique.\n\nWhy don't you give it a try? You should be able to get your ingredients here in the shop.\n\nNo matter how much we make, it never goes to waste. Bring me your loaves when you're done and I'll have someone share them with our friends, the Gilneans.", sourceObjective = "Make or obtain 10 pieces of Spice Bread.", progress = "I just love the smell of baking bread, especially spice bread. Don't you?", completion = "These are well-made, {name}. I hope you found baking as relaxing as I do.", sourceObjectiveStatus = "unverified-source-field" }
quests[29358] = { id = 29358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pining for Nuts", description = "The Shu'halo use pine nuts in so MANY dishes: meat, fish, vegetables, even baked into breads or sprinkled over sweet pastries.\n\nThe Earth Mother has blessed us in that the very BEST pine nuts come from the trees upon these very mesas. Simply gather pine cones and toast them over a cooking fire to release the nuts within.\n\nWould you please be so kind as to gather some? There are hardly ever enough to go around...", sourceObjective = "Obtain 30 Pine Nuts by toasting Mulgore Pine Cones from Thunder Bluff. Deliver the nuts to Aska Mistrunner in Thunder Bluff.", progress = "Have you found many of those tasty pine nuts?", completion = "You work so quickly!\n\nI'll see that these are distributed to the various chefs and bakers of Thunder Bluff.\n\nThank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[29359] = { id = 29359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Favorite", description = "Herring is one of the most sought-after fish in Darnassus, but not just any herring. The Kaldorei herring is native only to the waters surrounding Teldrassil.\n\nI try to keep a good supply of it because it's so versatile! I just finished smoking a batch of it, so I need to rebuild my stocks. Would you mind helping me? You can catch Kaldorei herring by fishing in Rut'theran Village.", sourceObjective = "Catch 8 Kaldorei Herring by fishing in Rut'theran Village.", progress = "Did you get those herring?", completion = "Thanks! I wonder what I should do with this batch...", sourceObjectiveStatus = "unverified-source-field" }
quests[29360] = { id = 29360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Would You Like Some Flies With That?", description = "It's not always about making food for the orcs, {class}.  This time, it's about making food for what will hopefully be their replacements.\n\nWe need to start small, we need to catch flies.  Flies love rotting meat, and we love rotting meat... as projectile weapons!\n\nCheck out the Meat Wagons for any extra bits of meat.  Where you find the meat, you'll find the flies.\n\nBring me 25 bloated flies, and then I can start on the next stage of our cooking plan.", sourceObjective = "Obtain 25 Bloated Flies from the \"meat\" near the Meat Wagons. Then return to Eunice Burch in Undercity.", progress = "I bet some of that \"meat\" is still good.", completion = "Ah!  Perfect!  Fat, slow and ready to be eaten!  Next up, we will feed them to our spiders.  Fatten them up, and then, we feed the spiders to the frogs...\n\nListen to me go on.  You don't need to know all the details.  This is just a small step in a grand cuisine in a grand scheme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29361] = { id = 29361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moat Monster!", description = "Sometimes fishing means throwing something back, {class}.\n\nWe've been overfeeding these frogs for just that occasion.  We've fed these frogs bloated spiders, that were fed bloated flies, and now, we are going to feed a real monster.\n\nThe moat above, in the Ruins of Lordaeron, is home to our very own moat monster.\n\nToday is feeding day.  But we must train it as well.  In this bag, you will find a decoy kit and some bloated frogs.  Use the decoy kit, then toss the frogs to the monster when it appears.", sourceObjective = "Use the Alliance Decoy Kit to summon the Moat Monster in the Ruins of Lordaeron. Then use the Bloated Frogs to feed the monster.", completion = "The dead feed the flies.  The flies feed the spiders.  The spiders feed the frogs.  The frogs feed our moat monster... It's a beautiful circle of life with the goal of ending life.", sourceObjectiveStatus = "unverified-source-field" }
quests[29362] = { id = 29362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Magic\" Mushrooms", description = "You know of the Pools of Vision, yes?\n\nThere is a sort of mushroom that grows there... not the tough, rank fungi that dominates the place, but smaller, more delicate caps that grow beneath them.\n\nThey are rare and quite delicious, adding a flavor to meat dishes that one might even call magical.\n\n...what? No, really. They just taste good. That's it.", sourceObjective = "Gather 6 \"Magic\" Mushrooms from the Pools of Vision in Thunder Bluff. Deliver them to Aska Mistrunner in Thunder Bluff.", progress = "Were you able to gather any mushrooms?", completion = "Thank you, {name}! I'm sure these will impart a simply magical taste to whatever dish they're used in.\n\nWhat? Stop looking at me like that!", sourceObjectiveStatus = "unverified-source-field" }
quests[29363] = { id = 29363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mulgore Spice Bread", description = "I am often asked, \"Aska, who is making all this Mulgore spice bread?!\"\n\nIt is a reasonable question. Our fine and noble bread is traded in countless settlements in the most far-away lands, even by our staunchest foes. IT'S JUST THAT GOOD.\n\nAnd the answer...?\n\nIt is \"YOU.\" Please take this packet of Mulgore spices and use it to turn bland, boring spice bread into MULGORE spice bread!", sourceObjective = "Use Mulgore Spices with Spice Bread to create 5 Fresh Mulgore Spice Bread (you may make your own Spice Bread or use someone else's). Deliver the bread to Aska Mistrunner in Thunder Bluff.", progress = "Have you baked that Mulgore spice bread, yet?", completion = "Ooo, that bread smells delicious. You are quite the baker, {name}.\n\nWho knows how far these exquisite loaves will go... I hear it's even popular among the draenei of the Azuremyst Isles!", sourceObjectiveStatus = "unverified-source-field" }
quests[29364] = { id = 29364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corn Mash", description = "One of Thunder Bluff's most important staples is cornmeal; bowls of corn may be found in nearly every home.\n\nWith so many of the local mills under constant attack by harpies, gnolls, reckless mining companies and Earth Mother knows what else, I often ask my students to help with the task of grinding corn into cornmeal.\n\nWould you care to help?", sourceObjective = "Help the inhabitants of Thunder Bluff make cornmeal by pounding bowls of Corn Kernels.", completion = "Much work is required to grind enough cornmeal for everyone's needs. Thank you for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29365] = { id = 29365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfectly Picked Portions", description = "Even the novice cook knows that a great dish begins with great ingredients.\n\nI have standing orders with merchants throughout Thunder Bluff, but I'd like to see how well you do at selecting the very best of what they have to offer.\n\nPlease make the rounds and gather perfect portions of meat, fish, vegetables and herbs from local merchant stalls.", sourceObjective = "Obtain four \"perfect portions\" from merchant stalls around Thunder Bluff. Deliver the ingredients to Aska Mistrunner in Thunder Bluff.", progress = "Have you gathered all the necessary ingredients?", completion = "<Aska examines the ingredients you have chosen.>\n\nMmmhmmm. Yes. Well done!\n\nI could not have chosen better myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[29371] = { id = 29371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Lose", description = "Well met, {class}. As we attempt to embrace the Wickerman ceremony, it is no surprise that the Horde would attempt to ruin our celebration.\n\nNow the prudent course of action may be to rise above the conflict and simply ignore the attacks.\n\nI admire those that take that high road, but I cannot help them.  But for those that seek to strike back... I can help them.  If you are interested, {class}, take this Dousing Agent and use it on the Horde's Wickerman in the Ruins of Lordaeron.", sourceObjective = "Use the Dousing Agent on the Wickerman in the Ruins of Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[29372] = { id = 29372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in Podunk", description = "Outlaws have kidnapped the sheriff!", sourceObjective = "Rescue the sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29373] = { id = 29373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in Podunk", description = "We never paid no heed to Sheriff Blundy, what with his gettin' all up-in-arms at all times 'bout his \"laws\" and his \"mis-de-meanors.\" But them dirty ol' McClintocks, and their cattle-rustlin' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin' and dead-or-alive-wantin', and come this past week they done took the law into their own hands - in the most literal of senses - by haulin' up and hi-jackin' the good Sheriff. As you can see, our humble", sourceObjective = "Rescue the sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29374] = { id = 29374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stink Bombs Away!", description = "The foolish Alliance have employed hags to fuel an attack on our city.  Well, as my sister once told me, \"Turnabout is fair play.\"\n\nWe will gladly return the favor.  Speak with my sister, and she will provide you with a broomstick flight over Stormwind.  While over Stormwind, drop stink bombs on the city and on the people.  Make them suffer!\n\nWe will show those hags in Stormwind who is the most powerful.", sourceObjective = "Speak with Crina Fenlow and take a broomstick flight over Stormwind city. Use the stink bombs to cover the city and its people.", sourceObjectiveStatus = "unverified-source-field" }
quests[29375] = { id = 29375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Up in Undercity", description = "Greetings, {class}!  Are you enjoying Hallow's End?  It seems that in response to our stink bombing Stormwind, the Alliance has decided to stink bomb our city.\n\nFortunately, we have magics that can handle the stink the Alliance bring us.  Use this Arcane Cleanser to remove the stink bombs from the city.", sourceObjective = "Use the Arcane Cleanser to remove stink bombs within the Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[29376] = { id = 29376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Build Up", description = "We burn the effigy of the Wickerman as a symbol of our struggle against those who would oppose us. We wear the ashes of the burnt Wickerman as a symbol of our neverending fight against those who would enslave us.\n\nUse the bonfire nearby and ignite the Wickerman.  Then take the ashes that lay nearby and spread them across your face.\n\nThese gestures will serve as a reminder to our enemies that we shall never yield.", sourceObjective = "Use the bonfire in front of the Wickerman to set it ablaze. Use the ashes on the ground near the Wickerman.", sourceObjectiveStatus = "unverified-source-field" }
quests[29377] = { id = 29377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Break Down", description = "Well met, {class}. As we revel in the Wickerman ceremony, it comes as no surprise that the Alliance would attempt to ruin our celebration.\n\nWe have an opportunity to make them pay.  If you are interested, {class}, take this Dousing Agent and use it on the Alliance's Wickerman in front of Stormwind.\n\nExtinguish their flame and revel in their misery, {class}.", sourceObjective = "Use the Dousing Agent on the Wickerman in front of Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29382] = { id = 29382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thanks, But No Thanks", description = "A holiday sweater may not be for everyone.\n\nThe receipt says that you can exchange it for gold at any Smokywood Pastures merchant.\n\nAll exchanges are final.", sourceObjective = "If you truly dislike your present, you can exchange it for gold by speaking to a Smokywood Pastures merchant.\n\nAll exchanges are final.", sourceObjectiveStatus = "unverified-source-field" }
quests[29383] = { id = 29383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thanks, But No Thanks", description = "A holiday sweater may not be for everyone.\n\nThe receipt says that you can exchange it for gold at any Smokywood Pastures merchant.\n\nAll exchanges are final.", sourceObjective = "If you truly dislike your present, you can exchange it for gold by speaking to a Smokywood Pastures merchant.\n\nAll exchanges are final.", sourceObjectiveStatus = "unverified-source-field" }
quests[29385] = { id = 29385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift" }
quests[29386] = { id = 29386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Mount Hyjal!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Jademoon in Stormwind Keep to gain entry into Moonglade.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", sourceObjective = "Speak to Cenarion Emissary Jademoon to secure transportation to Moonglade.", sourceObjectiveStatus = "unverified-source-field" }
quests[29387] = { id = 29387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Hyjal: Firelands Invasion!", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.\n\nWilling and able-bodied heroes of the Alliance should report to the Sanctuary of Malorne in Mount Hyjal immediately.", sourceObjective = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "Thank you for answering our call for aid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29388] = { id = 29388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Hyjal: Firelands Invasion!", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.\n\nWilling and able-bodied champions of the Horde should report to the Sanctuary of Malorne in Mount Hyjal immediately.", sourceObjective = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "Thank you for answering our call for aid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29389] = { id = 29389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Hyjal: Firelands Invasion!", description = "Your work has given us the advantage we need to mobilize against the denizens of the Firelands. We are gathering our invasion force just south of our position.\n\nWe could use your strength again, {race}. Speak with Matoclaw at the Sanctuary of Malorne. She is coordinating the invasion effort.", sourceObjective = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "Thank you for answering our call for aid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29390] = { id = 29390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Hyjal: Call of the Ancients", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands.\n\nWilling and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Lo'gosh, Tortolla, Aviana, and Aessina.\n\nNew travelers to Mount Hyjal may look for a Warchief's Command to Hyjal on any Horde call board.", sourceObjective = "Assist Lo'gosh, Tortolla, Aviana, and Aessina in Mount Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29391] = { id = 29391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Hyjal: Call of the Ancients", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands.\n\nWilling and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Goldrinn, Tortolla, Aviana, and Aessina.\n\nNew travelers to Mount Hyjal may look for a Hero's Call to Hyjal on any Alliance board.", sourceObjective = "Assist Goldrinn, Tortolla, Aviana, and Aessina in Mount Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29392] = { id = 29392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Heirlooms", description = "The last of my belongings were supposed to be arriving from Theramore today. The ship has arrived, but I haven't heard from the courier. The crate he was transporting had items that've been in my family for generations.\n\nWill you go down to Stormwind Harbor and see what's keeping him?", sourceObjective = "Search the cabin of the Hired Courier's ship in Stormwind Harbor for evidence of what might be delaying him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29394] = { id = 29394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew For Brewfest", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", sourceObjective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.\n\nProvided item:", completion = "There's always a need for more kegs at Brewfest, and Kharanos has a lot of kegs they can spare!\n\nI'll lend you the reins to one of my personal rams.\n\nEvery time you bring me a keg, I'll give you some tokens.  I'll even let you use the ram for a bit longer for every keg you bring me!\n\nTake heed! Once you start this, you won't be able to do it again until tomorrow.\n\nAre you sure you're ready to do this?", sourceObjectiveStatus = "unverified-source-field" }
quests[29396] = { id = 29396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Supplier of Souvenirs", description = "<sigh>\n\nDon't talk to me about last year's stein...\n\nI think our shady stein suppliers were somehow involved with that Twilight Hammer cult non-sense that errupted just before the elementals invaded.\n\nAnd that's why we have a new supplier and a better stein!\n\nHere's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", sourceObjective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "What's this?  A stein voucher?  So you like drinking?  Great!  After I give you this stein, go have a few drinks!  Then a few more.  Maybe have a few more after that...  Then, now this is important, come see me.\n\nLook, I know you'll be back eventually.  If you want your Brewfest tokens redeemed you have to see me.\n\nAnyways, here's the stein, and remember to talk to me later.", sourceObjectiveStatus = "unverified-source-field" }
quests[29397] = { id = 29397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Supplier of Souvenirs", description = "The less said about last year's stein, the better, {name}.  I'll tell you this, our previous supplier, they were shady.  Turns out they were involved in some cultist activities...\n\nWe can't work with people who are trying to destroy the world!!\n\nSo we have a new supplier and a new stein.\n\nTake this voucher to Belbi Quikswitch  near the back of the Brewfest camp.  She'll give you your free Brewfest stein.  She'll also handle any and all other Brewfest transactions that come up during the holiday.", sourceObjective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "Aww, it's just a stein voucher... Maybe you're just playing hard to get.  So here's this year's stein for you.\n\nBut I suspect I'll be seeing a lot more of you.  After all, if you want any Brewfest tokens redeemed, I'm your girl...\n\nOr maybe I'm his girl...  \n\nOooohhh... or his...", sourceObjectiveStatus = "unverified-source-field" }
quests[29398] = { id = 29398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fencing the Goods", description = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished.\n\nAs you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", sourceObjective = "Follow the spiders to their destination and question the man you find there.", sourceObjectiveStatus = "unverified-source-field" }
quests[29399] = { id = 29399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shopping Around", description = "I told the 'gentleman' that there might be a shop more suited to his needs in the Dwarven District. It's called the Shady Lady and you can find the entrance near the Canals on the western side of the district.\n\nQuincy Cutler is your man. He trades in merchandise an honest broker would never touch!", sourceObjective = "Make your way to the Shady Lady in Stormwind's Dwarven District and look for evidence of the crate-thief's visit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29400] = { id = 29400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Season for Celebration", description = "Well met, {class}.\n\nHallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken.\n\nTravel to the Ruins of Lordaeron above Undercity and speak to Darkcaller Yanka.  She can tell you more about the Wickerman ceremony.", sourceObjective = "Speak with Darkcaller Yanka in the Ruins of Lordaeron just outside the entrance to Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[29401] = { id = 29401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blown Away", description = "Please, <mister/miss>, you just gotta help me!\n\nMy pa brought me a bunch of balloons from the Darkmoon Faire. Best... gift... EVER! They're magical, you know, and never lose their floatiness!\n\nThere's just one thing...\n\nA big ol' gust of wind blew 'em right outta my hands. They're scattered all over Orgrimmar!\n\nI'd chase after 'em myself, but this city's so big I'd get lost for sure.\n\nCan you round 'em up for me before they float away?\n\nPlease?", sourceObjective = "Jaga wants you to collect 5 Windswept Balloons from Orgrimmar.", progress = "Did you find all of my balloons, mister?", completion = "This is GREAT! You did it!\n\nThanks, mister!", sourceObjectiveStatus = "unverified-source-field" }
quests[29402] = { id = 29402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Precautions", description = "I'd be wary of anyone identifying himself as the rightful owner of the crate and its contents. He didn't warn you of the danger?\n\nHere's a better idea: let's work together to recover the crate and ensure that its contents can't hurt anyone. To protect ourselves, we're going to need a draught made from a few ingredients that can be found around the city.\n\nBuy some arcane powder from a reagent merchant, get vials from an alchemy merchant, and pick some blood nettle from the fields north of the city.", sourceObjective = "Obtain 5 Crystal Vials, 5 Arcane Powder, and 5 Blood Nettle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29403] = { id = 29403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Collector's Agent", description = "According to Quincy, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara.\n\nThe archmage's faithful servant is to meet with the man who has the crate in the catacombs beneath the Cathedral of Light.\n\nYou must get there in time to intercept the exchange and retrieve the crate before it is lost to Xylem forever. When you have the crate, meet me at the Golden Keg.", sourceObjective = "Disrupt the meeting between Sanath Lim-yo and the thief in the catacombs beneath the Cathedral of Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[29411] = { id = 29411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Now?", description = "You've finally found the crate that Anson sent you to retrieve. However, it appears the archaeology student's warnings about the nature of the crate's contents were correct.\n\nThere's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Hudson Barnes, who believes it better to keep the crate's contents locked away?", sourceObjective = "Return the crate to Anson Hastings at the Gilded Rose in Stormwind.\n\n-OR-\n\nReturn the crate to Hudson Barnes at the Golden Keg in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29412] = { id = 29412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blown Away", description = "Please, <mister/miss>, you just gotta help me!\n\nFather bought me a bunch of balloons from the Darkmoon Faire. They're magical, you know, and never lose their floatiness!\n\nThere's just one thing...\n\nA gust of wind blew them out of my hands. They're scattered all over Stormwind!\n\nI'd chase after them myself, but this city's so big I'd get lost for sure.\n\nCan you find them for me before they float away?\n\nPlease?", sourceObjective = "Vin wants you to collect 5 Windswept Balloons from Stormwind.", progress = "Did you find all of my balloons, mister?", completion = "This is GREAT! You did it!\n\nThanks, mister!", sourceObjectiveStatus = "unverified-source-field" }
quests[29413] = { id = 29413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Creepy Crate", description = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems bonded to you and now it's yours." }
quests[29415] = { id = 29415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Heirlooms", description = "I told that courier to take the zeppelin, but no, he had to use the goblin ship! Well, now he's late and my precious family heirlooms are with him.\n\nIf you're willing to help, would you go down to the docks east of Orgrimmar, board the goblin ship and see what's keeping him?", sourceObjective = "Search the cabin of the Hired Courier's ship at the docks east of Orgrimmar  for evidence of what might be delaying him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29416] = { id = 29416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fencing the Goods", description = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished.\n\nAs you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", sourceObjective = "Follow the spiders to their destination and question the man you find there.", sourceObjectiveStatus = "unverified-source-field" }
quests[29425] = { id = 29425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shopping Around", description = "Look, I told that shady character that there might be a shop more open to his, uh, wares in the Drag. Droffer's and Son Salvage is the name of the place.\n\nLook for Dran Droffers. He oversees the 'salvage' of rare and valuable objects from all over Azeroth.", sourceObjective = "Make your way to Droffers and Son Salvage in Orgrimmar's Drag district and look for evidence of the crate-thief's visit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29426] = { id = 29426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Precautions", description = "So someone else hired you to retrieve this crate? I don't like the sound of that.\n\nThat crate's contents belong in the care of the Reliquary. The items it holds are very powerful and very dangerous.\n\nWe have to find the meeting that Dran set up between the thief and the collector, but first, we'll need to protect ourselves from the effects of handling that crate.\n\nBuy some arcane powder from a reagent merchant, get vials from an alchemy merchant, and pick some blood nettle in the Valley of Wisdom.", sourceObjective = "Obtain 5 Crystal Vials, 5 Arcane Powder, and 5 Blood Nettle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29427] = { id = 29427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Collector's Agent", description = "According to Dran, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara.\n\nThe archmage's faithful servant is to meet with the man who has the crate in a secluded corner of the courtyard in the Ruins of Lordaeron.\n\nQuickly, take the zeppelin to Tirisfal Glade!\n\nYou must get there in time to intercept the exchange and retrieve the crate before Xylem gets his hands on it. If you can get the crate, meet me at the Wyvern's Tail in the Valley of Honor.", sourceObjective = "Disrupt the meeting between Sanath Lim-yo and the thief in the Ruins of Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[29428] = { id = 29428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Now?", description = "You've finally found the crate that Edgar Goodwin sent you to retrieve. However, it appears the Reliquary representative's warnings about the nature of the crate's contents were correct.\n\nThere's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Delian Sunshade, who believes it better to keep the crate's contents locked away?", sourceObjective = "You may return the crate to either Edgar Goodwin at the Broken Tusk in Orgrimmar's Valley of Strength.\n\n-OR-\n\nReturn the crate to Delian Sunshade at the Wyvern's Tail in Orgrimmar's Valley of Honor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29429] = { id = 29429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Creepy Crate", description = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems bonded to you and now it's yours." }
quests[29430] = { id = 29430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friend in Need", description = "You know, I haven't seen Anson out here yet.\n\nLately, he's been spending all his time drinking himself into a stupor at the Gilded Rose.\n\nSomething must really be bothering him! Would you mind checking in on him?", sourceObjective = "Visit Anson Hastings at the Gilded Rose in Stormwind's Trade District.", sourceObjectiveStatus = "unverified-source-field" }
quests[29431] = { id = 29431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friend in Need", description = "There's something wrong with my friend, Edgar. Normally, he loves the Hallow's End festivities, but he's been sullen and reclusive lately.\n\nHe spends all his time in the Broken Tusk in Orgrimmar drinking with the orcs. Would you mind stopping by and seeing if there's anything you can do to cheer him up?", sourceObjective = "Speak with Edgar Goodwin at the Broken Tusk in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29433] = { id = 29433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Your Strength", description = "For some people, it's all fun and games until someone gets hurt.  I call those people, weak.\n\nTo be the strongest, you have to hurt someone or something.  You hurt yourself as you push your body to its limits.  You hurt those that threaten the well-being of others.\n\nIf you want to be the strongest, you have to fight.  How bad do you want it?\n\nI want you to crush those that would offer a challenge to you, then bring me back proof of your triumphs.", sourceObjective = "Kerri Hicks wants you to collect 250 Grisly Trophies. Trophies are obtained as long as you kill creatures that offer experience or honor and you have the Darkmoon Field Guide with you.", progress = "No pain, no gain.", completion = "Did you seek out worthy challenges, or did you simply find some field of boars and slaughter them?\n\nThere is a reason I am the strongest.\n\nPerhaps, one day you will see just how strong I really am, {class}.  Until then, keep pushing yourself.  But don't forget to take a break from time to time.\n\nLike now.  Here, enjoy the Darkmoon Faire.", sourceObjectiveStatus = "unverified-source-field" }
quests[29434] = { id = 29434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonk Commander", description = "Welcome to our humble little steam tank battle simulator!\n\nFor one token, you can demonstrate your tactical mastery by navigating the course and destroying the targets.", sourceObjective = "Use your Darkmoon Tonk to destroy 30 Tonk Targets in the time allowed.", progress = "Have tonk, will travel!", completion = "An impressive display!\n\nHere's your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[29436] = { id = 29436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Humanoid Cannonball", description = "For just one Darkmoon Game Token, you can ride the Blastenheimer 5000 Ultra Cannon.  But the fun doesn't end there!  We've placed a target in the water near the boardwalk.\n\nIf you can score five points from your landing, you can win some prize tickets!\n\nA bullseye gets you five points, a close shot three, and landing at least near it gets you one.\n\nHappy landings!", sourceObjective = "Accumulate 5 Cannon Target Points by landing near the target.", progress = "Happy landings!", completion = "Five points?  Good job!  Here are your prize tickets.\n\nEnjoy the rest of the Darkmoon Faire!", sourceObjectiveStatus = "unverified-source-field" }
quests[29437] = { id = 29437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Guardian", description = "Fandral Staghelm was kept prisoner here in Hyjal. It was the green dragon Alysra - one of my very own! - who was in charge of keeping Fandral secure.\n\nWe can only conclude that the Twilight's Hammer has gotten to her. You must confront her, {name}. Destroy her if you must - I cannot bear to see it.\n\nShe was last seen in the Ruins of Lar'donir, west of the World Tree.", sourceObjective = "Confront and slay Alysra at the Ruins of Lar'donir in Mount Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29438] = { id = 29438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Shoots, He Scores!", description = "Think you're a good shot?  Quick on the trigger?\n\nIt'll cost you just a single game token to test your skills.\n\nWhat do you say?  How good are you?", sourceObjective = "Score 25 points in 60 seconds.", progress = "Shooting static targets isn't always as easy at it seems.", completion = "I knew you could do it, {class}!  Here's your prize.  Enjoy the faire.", sourceObjectiveStatus = "unverified-source-field" }
quests[29439] = { id = 29439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the World-Shaman", description = "The Earthen Ring calls to you once more, {name}.\n\nAs a member of the Alliance, I know that you may have reservations working with the one you call Thrall, the former Warchief of the Horde. But he has specifically requested an Alliance hero to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.\n\nCast aside your doubts, {class}, and heed the world-shaman's call.\n\nYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree.", sourceObjective = "Speak with Thrall just south of the World Tree in Mount Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29440] = { id = 29440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the World-Shaman", description = "The Earthen Ring calls to you once more, {name}.\n\nThrall has cast aside his mantle as warchief of the Horde, but in his new role he needs the support of his people more than ever. He has requested one of the Horde's finest to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.\n\nYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree. Heed the call!", sourceObjective = "Speak with Thrall just south of the World Tree in Mount Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29441] = { id = 29441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Belly of the Beast" }
quests[29443] = { id = 29443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Crystal", description = "Power swirls inside this strange crystal. Perhaps it was once a magical focus, an energy source, or simply a good luck charm. There's no way to know for certain.\n\nThe Darkmoon Adventurer's Guide indicates that the crystal would be of interest to Professor Thaddeus Paleo at the Darkmoon Faire.", sourceObjective = "Bring the Imbued Crystal to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "Where did you get this crystal?\n\nThese are very rare and much sought-after by collectors. I would like to study this one and display it at the Faire. Would you accept a generous number of Darkmoon Faire tickets in trade?", sourceObjectiveStatus = "unverified-source-field" }
quests[29444] = { id = 29444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exotic Egg", description = "You're not certain what kind of creature this egg harbors, but it sure doesn't look like the egg of any ordinary animal.\n\nThe Darkmoon Adventurer's Guide says that an intrepid adventurer might come across any number of strange eggs in his travels. It further notes that the Darkmoon Faire's Zoo Bizarre is always interested in acquiring such specimens.\n\nTake the egg to Yebb Neblegear at the Darkmoon Faire.", sourceObjective = "Bring the Monstrous Egg to Yebb Neblegear at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "Where did you find this egg? There's sure to be something monstrous and wonderful inside! It will make a great addition to our zoo. Are you willing to part with it for a generous number of Darkmoon tickets?", sourceObjectiveStatus = "unverified-source-field" }
quests[29445] = { id = 29445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Intriguing Grimoire", description = "This massive spellbook reveals very little of its origins. Its pages are filled with a variety of spells and enchantments, only a few of which are familiar.\n\nThe Darkmoon Adventurer's Guide says the tome may be of some interest to Sayge, the famous gnoll fortuneteller at the Darkmoon Faire.", sourceObjective = "Bring the Mysterious Grimoire to Sayge at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "A strange grimoire, how interesting! I don't think I've seen its like before. I'd love to have it for my collection. Would you be willing to accept Darkmoon tickets in exchange?", sourceObjectiveStatus = "unverified-source-field" }
quests[29446] = { id = 29446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wondrous Weapon", description = "An inspection of the weapon reveals expert craftsmanship and intricate inlay work, but this is no ceremonial blade. Faint marks and nicks along the blade attest to its use in combat.\n\nThe Darkmoon Adventurer's Guide lists several types of rare and valuable weapons, leaving no doubt that Professor Thaddeus Paleo at the Darkmoon Faire would be interested in taking a look at this piece.", sourceObjective = "Bring the Ornate Weapon to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "Where did you find such a wonderful blade?\n\nThis is a work of astounding craftsmanship and worthy weapon for any champion. I would love to have it for display.\n\nWould you accept a generous number of Darkmoon Faire tickets in trade?", sourceObjectiveStatus = "unverified-source-field" }
quests[29451] = { id = 29451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Strategist", description = "This tome of strategy is the masterwork of the famous human general, Anduin Lothar. In his own words, the commander describes the proper deployment of forces and strategies needed to win almost any battle.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire would probably love to have a look at such a rare book.", sourceObjective = "Take A Treatise on Strategy to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "That doesn't look like a common book at all...", completion = "I don't know how you got your hands on this, and I know better than to ask. Could I convince you to part with it in exchange for Darkmoon tickets?", sourceObjectiveStatus = "unverified-source-field" }
quests[29452] = { id = 29452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Time Has Come", description = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.>\n\nYoung {class}, be still and hear my words.\n\nI am called to collect you, to deliver you, to one whose eye none can escape.\n\nFind me in Orgrimmar, mortal, for your time has come.", sourceObjective = "Speak to Ziradormi in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29453] = { id = 29453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Time Has Come", description = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.>\n\nYoung {class}, be still and hear my words.\n\nI am called to collect you, to deliver you, to one whose eye none can escape.\n\nFind me in Stormwind, mortal, for your time has come.", sourceObjective = "Speak to Coridormi in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29455] = { id = 29455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Turtle", description = "Hey there! Step right up!\n\nWhy not show everyone how skilled you are?  Just land three rings on the Darkmoon Turtle and you'll get a prize.\n\nFor one game token you can buy a stack of rings and show the world why we call you the \"Eagle Eyed {class}.\"", sourceObjective = "Land 3 rings on the Darkmoon Turtle.", progress = "How's that throwin' arm, champ?", completion = "I knew you could do it!\n\nWe'll take any extra rings you might have, and give you your prize ticket.\n\nHave fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[29456] = { id = 29456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Captured Banner", description = "This tattered banner bears a faded guild crest. This old banner must've seen more than its share of battles.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire collects banners and other relics of combat and he might be interested in acquiring this one. Show the banner to him next time you visit the Darkmoon Faire.", sourceObjective = "Bring the Banner of the Fallen to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "What a splendid banner! I'd love to have it for my collection.\n\nWould you be willing to trade it for some Darkmoon tickets?", sourceObjectiveStatus = "unverified-source-field" }
quests[29457] = { id = 29457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy's Insignia", description = "This battered badge carries the insignia of an enemy officer. While worth little more to you than the metal it's made from, this piece would have significant value to a collector of military memorabilia.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire is famous all over Azeroth for his large collection of military artifacts. Show the badge to him the next time you visit the Darkmoon Faire.", sourceObjective = "Bring the Captured Insignia to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "This is a remarkable example of an Alliance officer's insignia. While many of them visit the Faire, none are willing to part with their badges. Would you be willing to accept some Darkmoon tickets in trade?", sourceObjectiveStatus = "unverified-source-field" }
quests[29458] = { id = 29458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Journal", description = "This book is covered in battered leather stained with blood and mud. Leafing through the pages, you discover that it is a personal journal of an adventurer with a high opinion of himself and his adventures.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire might want to see something like this.", sourceObjective = "Bring the Adventurer's Journal to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "A remarkable find!\n\n<The professor browses the book's contents.>\n\nSome of these are hard to read, but if even a third of the contents of this journal are true, this is a real treasure. Would you trade it for a generous number of Darkmoon tickets?", sourceObjectiveStatus = "unverified-source-field" }
quests[29463] = { id = 29463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Hammer Time", description = "So you want to whack some gnolls?  Well you've come to the right place.\n\nYour goal is simple, score 30 points in a minute.\n\nUse the mallet I give you and get ready to whack.  Speak to me when you are ready to start.", sourceObjective = "Score 30 points by whacking Gnolls.", progress = "How did you do out there?", completion = "So you have managed to defeat the gnolls.  It felt good, didn't it?\n\nHere is your prize.  Enjoy the rest of the Darkmoon Faire!", sourceObjectiveStatus = "unverified-source-field" }
quests[29464] = { id = 29464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of Divination", description = "This collection of well-worn runestones has seen much use. The pieces seem old; you can't recognize any of the markings on their surfaces.\n\nPerhaps a scholar or a collector would know more about them. Bring them to Professor Thaddeus Paleo next time you're at the Darkmoon Faire.", sourceObjective = "Bring the Soothsayer's Runes to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What do you have there?", completion = "Where did you find this collection of runes? I haven't seen anything like this in years. It'll be a splendid mystery to unravel!\n\nWould you trade these for Darkmoon tickets?", sourceObjectiveStatus = "unverified-source-field" }
quests[29469] = { id = 29469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rearm, Reuse, Recycle", description = "Faire-goers just love the steam tonks! And when the Darkmoon Faire closes, these grounds will be littered with tonk scrap.\n\nIt'd be a shame to let all that good metal just sit in the dirt.\n\nIf you help me collect some of the larger scraps, I can use them to reforge broken tonk parts. It's a lot less expensive than buying new metal every time. What do you say?", sourceObjective = "Collect 6 pieces of Tonk Scrap from around the Darkmoon Faire grounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[29470] = { id = 29470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tan My Hide", description = "The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment.\n\nYou seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.", sourceObjective = "Scrape 4 Staked Skins around the grounds of the Darkmoon Faire.", sourceObjectiveStatus = "unverified-source-field" }
quests[29475] = { id = 29475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Engineering", description = "A skilled engineer can choose ONE specialization, and I know the secrets of goblin engineering.\n\nYou look like you're ready to blow things up, but I'll need some samples of your work.  Bring me twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep.\n\nSubmit these items to an engineering trainer in any of the capital cities and you'll be an official goblin engineer with access to all the schematics!", sourceObjective = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to an engineering trainer in any capital city.", progress = "Once I receive your crafted engineering items for my review, I will grant you the knowledge required to join the exclusive club of goblin engineers!", completion = "It appears you are indeed ready for proper training.  I dub you Goblin Engineer {name}!\n\nYou'll be able to access any Goblin Engineer for some diabolical creations.  Have fun and try not to blow your face off.", sourceObjectiveStatus = "unverified-source-field" }
quests[29477] = { id = 29477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomish Engineering", description = "A skilled engineer can choose ONE specialization, and I can teach you the ways of gnomish engineering.\n\nYou look like you know what you're doing, but I'll need some samples of your work.  Bring me six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to an engineering trainer in any of the capital cities and you'll be an official gnomish engineer with access to all the schematics!", sourceObjective = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to an engineering trainer in any capital city.", progress = "Once I receive your crafted engineering items for my review, you can become a certified gnomish engineer, granting you unlimited access to gnomish engineer schematics.", completion = "Today is the day you become a real engineer, {name}.  Don't worry about all those messy bombs and explosives, because it's time to shine!", sourceObjectiveStatus = "unverified-source-field" }
quests[29480] = { id = 29480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banners, Banners Everywhere!", description = "Isn't it wonderful to see Darkmoon banners everywhere? It's my favorite part of setting up, but we have so many old and tattered ones that need to be replaced.\n\nIf you've some skill with a needle and thread, would you mind making a banner from this kit and putting it up in some loose stone on the central rise in Thunder Bluff?\n\nYou can get the rest of the supplies you'll need from Shadi Mistrunner on the central rise of Thunder Bluff.", sourceObjective = "Use the Darkmoon Banner Kit to construct a Darkmoon Banner, then set it up in a pile of Loose Stones on Thunder Bluff's central rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[29481] = { id = 29481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir Master", description = "Elixirs are all about potency!  If you want to become an elixir master, I can teach you.\n\nI can't just train anyone, and I require proof that you are devoted before we continue.  Several flasks should be sufficient to show your dedication.\n\nRemember {name}, you can only learn ONE specialization, so if you complete your elixir training, then potion and transmutation specialization will no longer be available.", sourceObjective = "Bring a variety of flasks to an alchemy trainer in any capital city.", progress = "Have you the flasks?", completion = "Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[29482] = { id = 29482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transmutation Master", description = "Iron to gold, water to fire... if you want to become an transmutation master, then I can show you the way.\n\nThe training is very expensive, so bring me some of the finest material in the world, truegold.\n\nRemember {name}, you can only learn ONE specialization, so if you complete your transmutation training, then potion and elixir specialization will no longer be available.", sourceObjective = "Bring the requested materials to an alchemy trainer in any capital city.", progress = "Have you the gold?", completion = "Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[29506] = { id = 29506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fizzy Fusion", description = "I'm sure you've made a lot of potions in your time as an alchemist. How would you like to help with something a bit more light-hearted?\n\nI've always wanted to try creating a fruit-flavored version of our popular fizzy drinks. If you're willing to give it a try, you can buy some of the base drink from me and mix it with some moonberry juice.\n\nAny innkeeper in Elwynn Forest or Mulgore should be able to sell you enough juice to make your creation.", sourceObjective = "Use the Cocktail Shaker to combine Moonberry Juice and Fizzy Faire Drink to create 5 servings of Moonberry Fizz.", progress = "How's that moonberry fizz coming?", completion = "Your creation looks promising. With any luck, we'll soon have a new favorite!\n\nThanks for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[29507] = { id = 29507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fun for the Little Ones", description = "Children are always full of questions about what an archaeologist does and how it works, so I prepared a demonstration for them.\n\nI take artifacts and fossils and bury them in the sandbox beside the tent. The children get to dig and make their own discoveries, learn how bones fit together, and see how archaeology can teach them about history.\n\nIf you have any spare fossils, would you consider donating them to my side project?", sourceObjective = "Bring 15 Fossil Fragments collected with Archaeology to Professor Thaddeus Paleo at the Darkmoon Faire.", progress = "How about it? Want to donate some fossil fragments?", completion = "These are great! They're just the kinds of pieces the kids will be excited to 'discover'.", sourceObjectiveStatus = "unverified-source-field" }
quests[29508] = { id = 29508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby Needs Two Pair of Shoes", description = "You may have seen my horse, Baby, over near the wagons. She pulls the cart that hauls some of the animals in our Zoo Bizarre.\n\nShe's a hard worker and she tears through shoes like you wouldn't believe. It's about time for a new set. I've already bought the raw materials.\n\nAll you need to do is shape them over an anvil and apply them to Baby's feet. It's a quick job and worth some tickets, wouldn't you say?", sourceObjective = "Use the Iron Stock to craft 4 Horseshoes, then apply the Horseshoes to Baby at the Darkmoon Faire.", progress = "How's old Baby doing?", completion = "Thank you for your help, {name}! Here's the payment I promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[29509] = { id = 29509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Crunch in the Frog", description = "The Darkmoon Faire's crunchy frog is famous all over Azeroth!\n\nWe've just had a fresh batch of frogs delivered. How'd you like to help whip up a few and practice your cooking skills in the process?\n\nYou can get the flour you'll need to bread the frogs from any trade goods vendor in Elwynn Forest or Mulgore.", sourceObjective = "Prepare 5 Crunchy Frogs by breading your Plump Frogs with Simple Flour and then frying them in the cauldron behind Stamp Thunderhorn.", progress = "Do I smell fresh crunchy frog?", completion = "These are perfectly cooked, {name}. You've done an excellent job.", sourceObjectiveStatus = "unverified-source-field" }
quests[29510] = { id = 29510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Trash to Good Use", description = "People don't just come to the faire for fun and fortunes, {name}. Most want something to take home with them, so I help to create the magical trinkets visitors purchase with their prize tickets.\n\nFor that, I need a steady supply of soothsayer's dust. Take a look around the grounds and you'll see a lot of discarded weapons. Those are just the kinds of items that can be broken down into dust with enchanting skills like yours. Would you like to help?", sourceObjective = "Collect 6 Soothsayer's Dusts by disenchanting Discarded Weapons found around the grounds of the Darkmoon Faire.", progress = "Did you manage to get any of that soothsayer's dust?", completion = "This will help maintain my supply. Anytime you want to help, just look up old Sayge while the Darkmoon Faire's in town.", sourceObjectiveStatus = "unverified-source-field" }
quests[29511] = { id = 29511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talkin' Tonks", description = "The steam tonks are one of the Darkmoon Faire's most popular amusements. Our visitors love to test their skills for hours and hours, but the tonks take a real beating from all that fun.\n\nYou look like you know your way around a wrench. Mind helping me fix some of the damaged tonks and return them to working order? I'll compensate you for your time.", sourceObjective = "Repair 5 Damaged Steam Tonks around the grounds of the Darkmoon Faire.", progress = "You get those repairs done? Visitors are hard on those tonks and I'll need all of them up and running.", completion = "Good job getting those tonks back online. Here are those tickets I promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[29512] = { id = 29512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Carnies Back Together Again", description = "Working the Darkmoon Faire is a dangerous job, {name}. It's no surprise that many of our workers get injured setting up, taking down, and transporting all of its attractions.\n\nSome of the injured workers can be found around here, near the wagons. Others have gone to the healing tent for treatment. Would you take these bandages and see if you can help any of the injured workers?", sourceObjective = "Use the Darkmoon Bandage to heal 4 Injured Carnies.", progress = "Did you see to the needs of the injured workers?", completion = "Thank you for your help, {name}. It takes all of us to keep the faire up and running.", sourceObjectiveStatus = "unverified-source-field" }
quests[29513] = { id = 29513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spoilin' for Salty Sea Dogs", description = "We've just introduced another exciting new menu item, the salty sea dog. It's so popular, we can barely keep up with the demand!\n\nYou look like a decent angler and a spry {race}. Would you help me restock my fish supplies?\n\nWe wouldn't want to disappoint all those faire-goers looking to try a new food, would we?", sourceObjective = "Catch 5 Great Sea Herring in the ocean around Darkmoon Island.", progress = "Do you have those fish?", completion = "These are wonderful! Here are your tickets, as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[29514] = { id = 29514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herbs for Healing", description = "The little purple flowers that grow wild around the grounds aren't just pretty.\n\nThey play a role in everything from treating wounds to seasoning food.\n\nYou seem to have some talent for harvesting herbs. Would you like to help me rebuild my stocks of darkblossom?", sourceObjective = "Gather 6 Darkblossoms from around the Darkmoon Faire grounds.", progress = "How's that herb collection coming along?", completion = "Thank you, {name}. Anytime the Darkmoon Faire is in town, I'd be glad to have your help again.", sourceObjectiveStatus = "unverified-source-field" }
quests[29515] = { id = 29515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writing the Future", description = "As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures.\n\nMost times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice.\n\nMy stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. You can get the parchment you'll need from any trade goods vendor in Elwynn Forest or Mulgore.", sourceObjective = "Use the Bundle of Exotic Herbs to make Prophetic Ink and then combine the ink with Light Parchment to create Sayge's Fortunes.", progress = "Have you penned any of those fortunes?", completion = "These look just like mine. You've quite an eye for detail. Thank you for all your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29516] = { id = 29516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Faire Sparkling", description = "The Darkmoon Faire's performers and animals go through more jewelry than I'd ever imagined. Thankfully, the gems are just cut glass, but someone has to craft all of it.\n\nIf you've some skill as a jewelcrafter, perhaps you'd be willing to help craft some of the sparkling glass gems for our performers.\n\nSometimes you can find odd and amazing bits of glass around the grounds. Those make stunning gems when cut by someone with an eye for this craft.", sourceObjective = "Find Bits of Glass around the grounds of the Darkmoon Faire and craft it into 5 Sparkling 'Gemstones'.", progress = "Were you able to craft any replacement gems for the performers' jewelry?", completion = "Very nice work, {name}. You've quite a talent for this.", sourceObjectiveStatus = "unverified-source-field" }
